\begin{proposition}[Base sufficiency of H1--H4]\label{prop:minimal}
Hypotheses H1--H4 are sufficient for:
\begin{enumerate}[leftmargin=*]
\item existence and uniqueness of the metric projection onto ${C_{\mathrm{proj}}}$;
\item strict contraction of the transition operators $T_u$;
\item existence and uniqueness of the fixed point $f_u^\ast$ for each $u\in\U$;
\item compactness of the attractor family $\A^\ast=\{f_u^\ast:u\in\U\}$.
\end{enumerate}
They do not, by themselves, imply parameterwise non-collapse.
\end{proposition}

\begin{theorem}[Existence and Uniqueness of Projection]\label{thm:projection}
Under Hypothesis~\ref{hyp:H1}, the projection $\aleph(\Psi)$ exists and is unique for every $\Psi\in\Hilb$.
\end{theorem}

\begin{lemma}[Non-Expansiveness of the Projection]\label{lem:nonexp}
The map $\aleph:\Hilb\to{C_{\mathrm{proj}}}$ is non-expansive:
\[
\norm{\aleph(\Psi_1)-\aleph(\Psi_2)}\le \norm{\Psi_1-\Psi_2}
\qquad
\forall \Psi_1,\Psi_2\in\Hilb.
\]
\end{lemma}

\begin{theorem}[Contractivity]\label{thm:contraction}
Under Hypotheses~\ref{hyp:H1} and \ref{hyp:H2}, each $T_u$ is a strict contraction with Lipschitz constant at most $\norm{K}$:
\[
\norm{T_u(\Psi_1)-T_u(\Psi_2)}\le \norm{K}\,\norm{\Psi_1-\Psi_2}.
\]
\end{theorem}

\begin{theorem}[Compactness of the Attractor Family]\label{thm:compactness}
Under Hypotheses~\ref{hyp:H1}--\ref{hyp:H4}, the set $\A^\ast$ is compact in $\Hilb$.
\end{theorem}

\begin{theorem}[Structural Non-Collapsibility]\label{thm:noncollapse}
Under Hypotheses~\ref{hyp:H1}--\ref{hyp:H5}, the family is parameterwise non-collapsible:
\[
f_u^\ast\notin\mathcal{N}
\qquad
\forall u\in\U.
\]
\end{theorem}

\begin{proposition}[H5 Is Not Implied by H1--H4]\label{prop:h5-not-derived}
There exists a family satisfying H1--H4 for which H5 fails and its unique equilibrium is constant. There also exists a family satisfying H1--H4 for which H5 holds with a positive uniform distance of the equilibria from the constant subspace.
\end{proposition}

\begin{lemma}[The Disk Projection is Non-Expansive]\label{lem:disk-projection}
For all $v,w\in E$,
\[
\norm{P_E(v)-P_E(w)}_2\le \norm{v-w}_2.
\]
\end{lemma}

\begin{proposition}[Typed Non-Vacuity of the Computable Model]\label{prop:Q3verify}
The embedded constant-disk Golden Mean model is a fully typed, non-vacuous witness of the transition grammar:
\begin{enumerate}[leftmargin=*]
\item every operator has explicit domain and codomain;
\item the transition map $T_u$ is well-defined on $\mathcal{B}$;
\item the family admits unique fixed points and a compact parameter image;
\item the state contraction bound is explicit and computable.
\end{enumerate}
\end{proposition}

\begin{proposition}[Separate Witness for H5]
The family $\{T_u^{\mathrm{ac}}\}_{u\in\U}$ satisfies Hypotheses~\ref{hyp:H1}--\ref{hyp:H5} of Section~1.
\end{proposition}

\begin{proposition}[Parameter-Family Persistence is not State Spectrum]
Let $F:\U\to\mathcal{B}$ be the fixed-point family $F(u)=f_u^\ast$. Any persistence of parameter labels or family coordinates belongs to the variation of $F$ over $\U$, not to the state-transition spectrum of $DT_u(f_u^\ast)$ for fixed $u$.
\end{proposition}

\begin{proposition}[No Canonical Progressive Recovery under NFD]\label{thm:noprogressive}
Assume Hypothesis~\ref{hyp:nfd}. No finite canonical prefix map determines the inverse-limit identity object.
\end{proposition}

\begin{theorem}[Conditional Stability of Inverse-Limit Identity]\label{thm:rigidity}
Under RIG-1 through RIG-5 the two limits $I=\Id$ and $\widetilde I=\widetilde{\Id}$ are nonempty. Every history in either limit has a compatible history in the other within distance $C E_w$. Thus $d_H(I,\widetilde I)\leq C E_w$.
\end{theorem}

\begin{corollary}[Conditional Isomorphism Requires Extra Structure]
The Hausdorff bound alone is a statement about the distance between sets. A homeomorphism follows under the commuting-bijection hypotheses below.
\end{corollary}

\begin{proposition}[Transport by Commuting Coordinate Bijections]\label{prop:coherent-history-transport}
Suppose the weighted metric induces the product topology and homeomorphisms $h_t:S_t\to S_t$ satisfy $\widetilde\pi_t h_{t+1}=h_t\pi_t$. Then $H(x)_t=h_t(x_t)$ maps the limits homeomorphically, with inverse $H^{-1}(y)_t=h_t^{-1}(y_t)$. Its displacement in the common history space is at most $\sup_t w_t\sup_{z\in S_t}d_t(z,h_t(z))$.
\end{proposition}

\begin{theorem}[Finite-Budget Obstruction by Response Separation]\label{thm:non-simulability}
Under NS-1--NS-3, let $A\subseteq X$ be a finite set such that for each distinct $x,y\in A$ there is $j$ with $\rho_j(F_j(x),F_j(y))>2\eta$. Then $|A|\leq 2^B$. For exact fidelity, a code exists exactly when the number of equivalence classes of $x\sim y$ defined by $F_j(x)=F_j(y)$ for all $j$ is at most $2^B$.
\end{theorem}

\begin{theorem}[Approximation Barrier]\label{thm:finite-budget-approximation}
On the binary prefix tower $S_t=\{0,1\}^{t}$ with weights $w_t=2^{-t}$ and discrete stage metrics, use $Y=X=\{0,1\}^{\mathbb N}$ as the decoded history space, with $d_w(x,y)=2^{-m}$ at the first differing bit $m\geq1$. Among all encoders with at most $2^B$ states and decoders into $X$, the minimum worst-case $d_w$ error is $2^{-(B+1)}$. Exact recovery of all finite prefix responses requires unbounded $B$ as the query horizon increases.
\end{theorem}

\begin{proposition}[Endomorphisms Preserving All Canonical Projections]
If $F:\mathcal I\to\mathcal I$ satisfies $p_t\circ F=p_t$ for every $t$, then $F=\operatorname{Id}$. This does not exclude endomorphisms with nonidentity coordinate actions.
\end{proposition}

\begin{theorem}[E0 is Necessary]\label{thm:e0-necessary}
If $|\mathcal{E}| = 1$, then every structural assignment is constant and no phenomenological classification is possible.
\end{theorem}

\begin{theorem}[Controlled Compatibility Is Sufficient]\label{thm:e1-necessary}
E1 guarantees existence of the limit with the error bound in Proposition~\ref{prop:unique-phi}. Absolute summability is sufficient, not necessary for an arbitrary convergent family.
\end{theorem}

\begin{theorem}[Non-Factorization Is an Independent Requirement]\label{thm:e2-necessary}
E2 excludes readouts determined by a single canonical finite cut. The inverse-limit construction and E1 alone do not imply E2.
\end{theorem}

\begin{theorem}[Logical Dependencies of the Assignment Conditions]\label{thm:minimality}
On a nonempty trajectory domain, E2 implies E0. E1 does not imply E2. There exist assignments satisfying E0, the revised E1 and E2 simultaneously. Consequently these three conditions are not an independent minimal axiom basis as originally stated.
\end{theorem}

\begin{proposition}[Exact Compatibility Forces Finite-Cut Factorization]\label{prop:exact-e1-obstruction}
On a nonempty trajectory domain, if $\phi_{t+1}(p_{t+1}x)=\phi_t(p_tx)$ for every $x,t$, then the limit assignment satisfies $\Phi=\phi_0\circ p_0$. It cannot satisfy E2. The controlled E1 above replaces that exact equality, rather than assuming it together with E2.
\end{proposition}

\begin{proposition}[Sharp Error for Arbitrary Binary Codes]\label{prop:ternary-arbitrary-code}
For the ternary assignment above, let an encoder choose at most $2^B$ states as an arbitrary function of the whole history, and let each state decode to any real number. The minimum worst-case absolute error is $1/(2\cdot3^B)$ for every integer $B\geq0$.
\end{proposition}

\begin{proposition}[Setwise Invariance Does Not Supply Continuity]\label{prop:readout-continuity-control}
Controlled E1 and E2 can hold for a discontinuous assignment, even if the identity domain is fixed under every declared intervention.
\end{proposition}

\begin{proposition}[Setwise and Pointwise Transport Are Distinct]\label{prop:transport-control}
Preserving an identity domain as a set does not guarantee equal values of a common readout on transported states.
\end{proposition}

\begin{theorem}[Metric Data Required by Quantitative Formulas]\label{thm:h3-necessary}
The distance-based fragmentation and loss functionals used here require a declared metric, or a pseudometric with a stated quotient convention. Topological continuity can be defined without a metric. Completeness is used for the Cauchy-limit guarantee of E1.
\end{theorem}

\begin{proposition}[Completeness and Existence of Limits]\label{prop:complete-necessary}
Without completeness, the conclusion that every E1-type Cauchy family has its limit in the declared codomain can fail. Completeness is not necessary for a family whose limit is already known to belong to that codomain.
\end{proposition}

\begin{corollary}[Fragmentability and Continuity Are Distinct]
The positive-displacement conclusion does not establish a topological discontinuity. A continuous assignment may be fragmentable under a state-changing intervention.
\end{corollary}

\begin{corollary}[Invariance on the Audited Zero-Displacement Branch]
A CCR model satisfying the zero-displacement comparison hypothesis has invariant assignment values under all interventions in its declared finite-cost class.
\end{corollary}

\begin{theorem}[Conditional Classification by Audited Branches]\label{thm:dichotomy}
Suppose a model supplies the positive-displacement branch and lower bound whenever $M_\Omega<\infty$, and supplies continuous finite readouts and the zero-displacement branch whenever $M_\Omega=+\infty$. Then its finite regime is fragmentable and its infinite regime has a continuous, perturbation-invariant assignment. The mass cases are exclusive; fragmentability and topological continuity need not be exclusive properties.
\end{theorem}

\begin{proposition}[The Mass Label Does Not Define Assignment Existence]
For fixed identity domain, codomain and readout family, the class defined by E0--E2 is independent of a numerical label $M_\Omega$. A claim that $M_\Omega=0$ excludes assignments needs an additional link to the domain or admissible readouts.
\end{proposition}

\begin{proposition}[Deformable Branch with Comparison Data]
For $0<M_\Omega<\infty$, the positive-displacement and lower-bound hypotheses of Theorem~\ref{thm:fragmentation} imply fragmentability.
\end{proposition}

\begin{proposition}[Rigid Branch with Comparison Data]
For $M_\Omega=+\infty$, continuous finite readouts under E1 imply continuity, and the zero-displacement branch implies perturbation invariance. These are the respective hypotheses of Theorem~\ref{thm:forced-continuity}.
\end{proposition}

\begin{lemma}[Inheritance under Audited Fixed Transport]
An assignment satisfying the zero-displacement comparison branch inherits invariance under that declared intervention class. This applies to CCR realizations only after checking that branch.
\end{lemma}

\begin{lemma}[Bridge Lemma]\label{lem:null-bridge}
For any defined $e\in\E$, distance $\dE(e,\nullphi)=0$ implies $e=\nullphi$. No CCR assumption is needed.
\end{lemma}

\begin{corollary}[Conditional Forced Non-Nullity]\label{cor:forced-non-nullity}
Under the separated-pair hypotheses, at least one witness image is non-null. If one endpoint is fixed at null, the other has null distance at least $C\epsilon$. CCR alone does not select a non-null endpoint or guarantee a stable regime.
\end{corollary}

\begin{theorem}[Minimal Positive Witness Regime]\label{thm:minimal-positive-regime}
The finite positive witness image $A$ is non-empty and has a minimal element. If its two possible values are comparable, it has a unique least element. No ambient order completeness is needed. This does not prove a least member of all of $\Eplus$.
\end{theorem}

\begin{theorem}[Anchored Witness Intensity Bound]\label{thm:universal-intensity-bound}
If one endpoint is null, the other image $e$ is the unique positive member of $A$ and satisfies $\iota_{A_0}(e)=r(e)\geq C\epsilon>0$. Without that anchor, only $\max_i r(\Phi(z_i))\geq C\epsilon/2$ follows. No universal global intensity bound is claimed.
\end{theorem}

\begin{theorem}[Conditional Phenomenological Closure]\label{thm:forced-phenomenological-closure}
A declared detected pair gives joint null exclusion and a minimal positive member of its finite image. A null anchor gives a unique positive witness value and the anchored quantitative bound. Uniqueness in the ambient regime space, temporal stability and CCR realizability require further hypotheses and constructions.
\end{theorem}

\begin{proposition}[Profinite Bound]\label{prop:profinite-bound}
A profinite witness pair with declared positive separation $\epsilon$, certified lower constant $C_{\mathrm{prof}}>0$ and one null endpoint gives $r(e)\geq C_{\mathrm{prof}}\epsilon$. Summable coordinate costs do not by themselves certify CCR.
\end{proposition}

\begin{proposition}[Symbolic Bound]\label{prop:symbolic-bound}
The same anchored conclusion holds for a symbolic witness with its audited metric and lower constant. The full binary shift with complement intervention and summable coordinate-change costs is a control against automatic infinite mass.
\end{proposition}

\begin{proposition}[Boundary Discipline]
BaseCore may define structures that downstream layers use, but it does not claim downstream closure. In particular, BaseCore does not by itself own runtime thresholds, bridge admissibility, human-comparator programs, phenomenality burdens, or Papers 7--9.
\end{proposition}

\begin{proposition}[No automatic downstream promotion]
Let $\mathfrak{E}=(\mathcal{O},\mathcal{H},\mathcal{R},\mathcal{B})$ be a BaseCore export object and let $P$ be a predicate introduced outside BaseCore. If $P\notin\mathcal{R}$, then BaseCore does not entail $P$ unless an admissible extension supplies an additional bridge from $\mathcal{H}$ to $P$.
\end{proposition}

\begin{proposition}[Boundary preservation under finite implementations]
Suppose a finite implementation produces diagnostics for a downstream predicate $P$ over a bounded horizon. If the implementation does not prove that the diagnostics are invariant over the relevant mathematical class, then the diagnostics remain implementation evidence for $P$ and do not promote $P$ to a BaseCore result.
\end{proposition}

\begin{lemma}[Two Factor Fibers Cannot Share a Nonconstant Label]\label{lem:two-factor-label-obstruction}
Let $\chi:A\to A_1\times A_2$ be surjective. If a label $g:A\to L$ is constant on every fiber of each of the two factor projections of $\chi$, then $g$ is constant on $A$.
\end{lemma}

\begin{proposition}[Each invariant is individually necessary]\label{prop:invariant-necessity}
If any one of $\Iper,\allowbreak \Iri,\allowbreak \Iint,\allowbreak \Icont,\allowbreak \Idiff,\allowbreak \Ileg$ fails, then $S\notin\Critop$.
\end{proposition}

\begin{proposition}[Well-definedness of the certified partition]\label{prop:qop-welldefined}
On any declared support $\Aset$ with a structurally closed decoder family, the relation $\sim_{\Partop,S}$ is an equivalence relation. This conclusion does not require the other critical invariants; certification of criterion membership still does.
\end{proposition}

\begin{theorem}[Rupture by Invariant Loss]\label{thm:rupture}
If a critical invariant has no admissible witness on any support, then $S\notin\Critop$. Loss of a witness on one chosen support invalidates that support's certificate, but does not exclude a certificate on another support without further analysis. Quotient undefinedness, triviality and loss of legibility are not mutually exclusive labels and need not accompany every loss of criterion membership.
\end{theorem}

\begin{theorem}[Minimality of the six-invariant basis]\label{thm:invariant-basis-minimality}
Let $\mathfrak{U}$ be any admissible universe containing at least one single-rupture witness for each invariant. Then no strict subset of $\mathfrak{I}$ is extensionally equivalent to $\Critop$ on $\mathfrak{U}$.
\end{theorem}

\begin{proposition}[Legibility is jointly constrained]\label{prop:legibility}
No single legibility metric is sufficient for $\Ileg$. The invariant requires simultaneous control of separation, admissible noise robustness, persistence window, intervention fidelity, negative controls, and structured compressibility.
\end{proposition}

\begin{theorem}[Certified criterion membership]
If $\Cert(S)$ exists and satisfies Criterion~\ref{crit:cert}, then $S\in\Critop$ and $\Partop(S)$ is well-defined.
\end{theorem}

\begin{proposition}[Ablation prediction]\label{prop:ablation-prediction}
Let $c$ be a fixed certificate with its stored support, witnesses and margins.
If an intervention makes a required obligation false for the transported tuple,
that tuple is no longer a valid certificate. This does not exclude replacement
witnesses on the same support or a replacement certificate on another support.
\end{proposition}

\begin{lemma}[Directed Resonance Bound]\label{lem:directed-resonance-bound}
Under the first two regularity conditions, $R$ is $L_R$-Lipschitz in the normalized Hilbert norm.
\end{lemma}

\begin{theorem}[Hilbert--Discrete Bridge]\label{thm:bridge}
Assume Hypotheses~\ref{hyp:H1}--\ref{hyp:H4} and Assumptions~\ref{ass:discrete-regularity} and~\ref{ass:bridge-consistency}. For $f_0\in C$ and $\mathbf{x}_0\in C_N$, set $f_{n+1}=T_u(f_n)$ and $\mathbf{x}_{n+1}=\widehat T_{N,u}^{e,\phi}(\mathbf{x}_n)$ with fixed $u,e,\phi$. Then, for every $n\geq0$,
\[
\norm{J_N\mathbf{x}_n-f_n}_{\Hilb}
\leq\kappa^n\norm{J_N\mathbf{x}_0-f_0}_{\Hilb}
+\eps_N\frac{1-\kappa^n}{1-\kappa}.
\]
The convention $\kappa^0=1$ applies also at $\kappa=0$. If $\eps_N\to0$, the transition maps converge uniformly on $C$.
\end{theorem}

\begin{lemma}[Cell-Average Error for a Lipschitz Profile]\label{lem:cell-average-error}
Let $a:[0,1]\to\mathbb{R}$ be $L_a$-Lipschitz and put $P_N=J_NJ_N^\dagger$. Then
\[
\norm{P_Na-a}_{L^2}\leq\frac{L_a}{\sqrt{12}\,N}.
\]
\end{lemma}

\begin{theorem}[Exact Commutation Requires a Common Fixed Point]\label{thm:sigma-common-fixed-point}
Let $\Aset$ be a nonempty complete metric space. If a strict contraction $\Sigma:\Aset\to\Aset$ commutes with each admissible self-map $\Phi_u$, then its unique fixed point is fixed by every $\Phi_u$. On the common tower support of Paper V, the two neutral controls with phase commands $0$ and $1/4$ exclude such a $\Sigma$.
\end{theorem}

\begin{proposition}[Global Phase Obstruction and Fibre Accuracy on the Writable Tower]\label{prop:sigma-tower-defect-floor}
On the safe writable tower of Paper V \cite{paper5}, use the branch distance $\max(\rho,|c-c'|,|m-m'|/4)$ and distance one across profiles. For a global $L$-contraction the two native neutral phases $0,1/4$ force uniform defect at least $(1-L)/8$. The full neutral family of phases forces defect at least $(1-L)/2$. In fact with all phases the sharp uniform floor is $1/2$ for every $L<1$, even allowing the other writable commands, and uniform reconstruction error is at least $1/2$.

In contrast, the depth-$d$ truncation $T_d$ of Proposition~\ref{prop:sigma-fibre-truncation}, extended to retain memory as well as phase, profile and the first $d\ge1$ digits, is constant on each retained-data fibre. Its uniform error is at most $3^{-d}$ and its uniform commutation defect for each native command is exactly $2\cdot3^{-(d+1)}$. For a candidate $\Sigma$ with $\sup_x d(\Sigma x,T_dx)\le\zeta$, its defect against any native neutral control is at least $2\cdot3^{-(d+1)}-3\zeta/2$.
\end{proposition}

\begin{proposition}[Conditional obstruction to self-reference within $\Cop$]\label{prop:sigma-not-entailed}
If a complete admissible support witnessing $\Cop$ has no common fixed point of its admitted interventions, then it has no self-model of Definition~\ref{def:sigma-op} on that support. Such a system refutes entailment on the declared support once all six upstream witnesses are supplied.
\end{proposition}

\begin{theorem}[$\Cop$ entails $\Piop$]\label{thm:cop-entails-pi}
If $S\in\Cop$, then $\Piop(S)=1$.
\end{theorem}

\begin{corollary}[No plurality of independent operational perspectives]\label{cor:no-independent-perspectives}
For $S\in\Cop$, any decomposition into multiple independent operational perspectives is inadmissible unless it fails to preserve either the rigid identity witness or the non-factorization witness.
\end{corollary}

\begin{theorem}[$\Cop$ Entails Population-Level $\Iotaop$ under the L4 Protocol]\label{thm:cop-entails-iota}
If $S\in\Cop$, the frozen population and prediction supplied by its L4 witness satisfy $\Iotaop=1$ on that protocol.
\end{theorem}

\begin{corollary}[$\Cop$ entails well-defined certified response classes]\label{cor:cop-qop}
If $S\in\Cop$, then $\Qop(S)$ is well-defined.
\end{corollary}

\begin{proposition}[Non-triviality of $\Qop(S)$ under $\Idiff$]\label{prop:qop-nontrivial}
If $S\in\Cop$ and the differentiation witness of $\Idiff(S)=1$ separates at least two certified decoder classes, then $|\Qop(S)|>1$.
\end{proposition}

\begin{proposition}[$\Cop$ gives weak non-null operational phenomenology]\label{prop:weak-phi}
If $S\in\Cop$, then the operational-continuity and non-null burdens required for weak $\Phiop$ are present on admissible support.
\end{proposition}

\begin{proposition}[$\Cop$ does not entail CCR-strength $\Phiop$]\label{prop:cop-not-ccr}
Membership in $\Cop$ does not entail CCR-strength operational phenomenology.
\end{proposition}

\begin{theorem}[$\Subbridge$ is conditionally generated by $\Cop+\Sigma1$]\label{thm:subbridge-generated}
Let $S$ be an admissible system. If $S\in\Cop$, $S$ satisfies $\Sigma1$, and the differentiation witness is decoder-visible, then $S\in\Subbridge$.
\end{theorem}

\begin{theorem}[$\Subbridge$ is a subclass of $\Cop$]\label{thm:subbridge-subset}
\[
\Subbridge \subseteq \Cop.
\]
Moreover, if $\Sigma1$ is not entailed by $\Cop$, then the inclusion is proper.
\end{theorem}

\begin{corollary}[Full Paper 7 subjecthood remains stronger]\label{cor:paper7-stronger}
Full Paper 7 indexed continuity-and-control criterion $\Subop$ is not established by Theorem~\ref{thm:subbridge-generated}. To lift $\Subbridge$ into $\Subop$, one must additionally certify $\Lop$ and the Paper 7 subject-specific descriptors not reduced to $\Sigma1$.
\end{corollary}

\begin{corollary}[No equivalence between $\Cop$ and indexed continuity-and-control criterion]\label{cor:no-equivalence}
The bridge paper proves neither $\Cop=\Subbridge$ nor $\Cop=\Subop$. It proves only that several bridge components are entailed by $\Cop$, while self-reference and full subjecthood require additional burdens.
\end{corollary}

\begin{proposition}[Boundary preservation]\label{prop:boundary-preservation}
No theorem in this paper converts an operational predicate into a phenomenal, biological, psychological, or moral predicate.
\end{proposition}

\begin{theorem}[Layer preservation]\label{thm:layer-preservation}
If a theorem in Papers 1--5 is stated only in the demonstrated layer, then it
cannot be promoted to an interpretive-layer conclusion by terminology alone.
\end{theorem}

\begin{theorem}[Additional Conditions in the Bridge Ladder]\label{thm:bridge-ladder-strict}
Each step in the ladder introduces an explicit additional burden. Strictness of any class inclusion requires an admissible separating witness.
\end{theorem}

\begin{proposition}[Runtime non-promotion]\label{prop:runtime-non-promotion}
No artifact with status \texttt{proxy}, \texttt{estimator},
\texttt{certificate}, or \texttt{internal\_support} entails
\texttt{external\_validation}.
\end{proposition}

\begin{theorem}[Seven Countermodel Obligations for $\Cop$]\label{thm:nonentailment-library}
The following seven tests are candidate routes for distinguishing $\Cop$ from self-reference $\Sigma1$, phenomenal experience, biological life, human subjectivity, Nagel-style qualia, CCR-strength temporal continuity, and agency. A mathematical non-entailment requires the relevant admissible countermodel and a typed target predicate.
\end{theorem}

\begin{theorem}[Self-model strength chain]\label{thm:sigma-chain}
\[
\Sigma1_{\mathrm{comm}}
\Rightarrow
\Sigma1_{\mathrm{strong}}
\Rightarrow
\Sigma1_{\mathrm{weak}}.
\]
The converses are not valid in general.
\end{theorem}

\begin{proposition}[OSSI and $\Sigma1$ are orthogonal additions]\label{prop:ossi-sigma-orthogonal}
The open-system individuation burden OSSI and the self-model burden $\Sigma1$
are not mutually entailing in the present corpus.
\end{proposition}

\begin{proposition}[Template soundness]
A template yields a non-entailment if a realized model retains all the witnesses required by $\Cop$ and its typed target predicate is proved false.
\end{proposition}

\begin{corollary}[Global Self-Reference and Indexed Valuation Are Not Forced]\label{cor:infinite-cop-nonentailed}
The global Hilbert--prefix system of Paper V satisfies the complete six-predicate criterion in its declared model universe. Nevertheless it admits no global strict contraction $\Sigma:A\to A$ commuting exactly with every admitted intervention, and its matched exchange protocol gives zero valuation asymmetry as in Paper VIII. Thus neither that global self-reference requirement nor the seven-coordinate indexed class follows from $\Cop$ alone.
\end{corollary}

\begin{proposition}[R0 under Controlled-System Isomorphism]\label{prop:a0-closed}
Let $h:X_{\rm adm}\to X'_{\rm adm}$ and $v:E\to E'$ be bijections and put $F'(hx,ve)=hF(x,e)$. R0 holds for one controlled system exactly when it holds for the other.
\end{proposition}

\begin{proposition}[Prefix Representation of a Trajectory Domain]\label{prop:necessity}
Let $H\subseteq X^{\mathbb N}$ be nonempty and let $S_n$ be its prefixes through time $n$, with deletion maps. These maps are surjective and $H$ embeds in their nonempty inverse limit. If $X$ is compact metric and $H$ is closed, the embedding is a homeomorphism onto that limit.
\end{proposition}

\begin{proposition}[Non-locality of Identity]\label{prop:nonlocality}
Let $p_t:\mathcal I\to S_t$ be canonical evaluation. Assume active bonding maps are surjective. If some $n\ge t$ has distinct $a,b\in S_{n+1}$ with $\pi_{n+1\to n}(a)=\pi_{n+1\to n}(b)$, then $p_t$ is not injective. Every map factoring through $p_t$ fails to separate all compatible histories. Branching arbitrarily far out obstructs every finite canonical cut. This does not exclude arbitrary set injections $\mathcal I\hookrightarrow S_t$.
\end{proposition}

\begin{theorem}[No Progressive Identity Construction]\label{thm:noprogressive}
If $p_0$ is noninjective, no compatible forward sections $f_t:S_t\to S_{t+1}$ with $\pi_{t+1\to t}f_t=\mathrm{id}$ generate all of $\mathcal I$ as the orbital history space $x_{t+1}=f_t(x_t)$.
\end{theorem}

\begin{theorem}[Universal Representation of a Fixed Compatible Cone]\label{thm:minimal}
For a declared inverse system, every coherent family $q_n:J\to S_n$ induces a unique map $q:J\to\mathcal I$ with $p_nq=q_n$. In the topological category, continuous $q_n$ give continuous $q$ in the product-subspace topology.
\end{theorem}

\begin{lemma}[Stability of Compatibility]\label{lem:stability}
Use common compact metric stages and two continuous bonding families with $w_t\operatorname{diam}(S_t)\to0$. Assume $D_w<\infty$. For each $f\in\{\pi_t,\widetilde\pi_t\}$ and each $u\in S_{t+1},v\in S_t$, assume an exact lift $u'$ with $f(u')=v$ and $d_{t+1}(u,u')\leq K_t d_t(f(u),v)$ for some common $K_t>0$. Set $q_t=w_{t+1}K_t/w_t$ and $C=\sup_{0\leq k\leq t}\prod_{j=k}^t q_j<\infty$. The limits $I=\mathcal I$ and $\widetilde I=\widetilde{\mathcal I}$ are nonempty and $d_H(I,\widetilde I)\leq C D_w$ in the common history space.
\end{lemma}

\begin{theorem}[Rigidity of the Identity under Coherent Transport]\label{thm:rigidity}
Suppose the weighted metric induces the product topology and homeomorphisms $h_t:S_t\to S_t$ satisfy $\widetilde\pi_t h_{t+1}=h_t\pi_t$. Then $H(x)_t=h_t(x_t)$ maps the limits homeomorphically, with inverse $H^{-1}(y)_t=h_t^{-1}(y_t)$. Its displacement in the common history space is at most $\sup_t w_t\sup_{z\in S_t}d_t(z,h_t(z))$.
\end{theorem}

\begin{corollary}[Small Displacement of Coherent Transports]
For a family of commuting coordinate homeomorphisms, if $\sup_t w_t\sup_{z\in S_t}d_t(z,h_t(z))$ tends to zero, then the induced transports converge uniformly to the inclusion of $I$ in the common history space.
\end{corollary}

\begin{theorem}[Finite Resistance Requires an Admitted Deformation Witness]\label{thm:lml}
In a declared common metric space, finite resistance for a candidate of this class is equivalent to the existence of an admitted intervention of finite cost with positive Hausdorff deformation. Finite latent dimension and Lipschitz dynamics alone permit systems without such a witness.
\end{theorem}

\begin{theorem}[Finite Witnesses for Deformation Resistance]\label{thm:detectability}
Assume the specified intervention sector and common metric of Definition~\ref{def:ontmass}. For any finite family of interventions of finite cost with exactly known Hausdorff distances, its infimum ratio is an upper bound on $M_\Omega$. This infimum is finite exactly when the family contains a positive-deformation witness. Moreover $M_\Omega<+\infty$ exactly when the full sector contains such a finite-cost witness. Exhaustion by nested families gives convergence to $M_\Omega$ if their union contains witnesses with ratios arbitrarily close to the sector infimum.
\end{theorem}

\begin{theorem}[Positive Separation at a Fixed Scale]\label{thm:spectral-coupling}
If $\mathcal I$ is a nonempty compact metric space and $T_\Phi$ is continuous and injective, then $\omega_T(r)>0$ at every scale in its domain. The infimum is attained.
\end{theorem}

\begin{corollary}[Resolution and Coercivity]\label{cor:spectral-derivation}
If each of two observed values has error at most $\eta$ in $d_O$, then true separation in $d_w$ of at least $r$ gives measured separation at least $\omega_T(r)-2\eta$. A global linear bound requires a positive lower Lipschitz constant $c$, established or assumed for the stated domain.
\end{corollary}

\begin{proposition}[Observational Isolation Does Not Determine Interventional Invariance]\label{prop:causal-rigid}
Even $\beth_q=1$ does not determine whether the state law is invariant under interventions on $Y$. With a structural model $X=f(Y,Z)$ and a fixed exogenous law for $Z$, the law under $\mathrm{do}(Y=y)$ is the pushforward of that law by $f(y,\cdot)$. Invariance of these laws on a specified intervention family requires equality of the corresponding pushforwards.
\end{proposition}

\begin{theorem}[Strong Uniqueness]\label{thm:uniqueness}
Within one operating channel of Definition~\ref{def:coexist}, at most one CCR identity assignment exists up to the declared zero-deformation equivalence, provided the connecting moves belong to that same CCR comparison sector. Two coexisting assignments therefore have $d_{\mathrm{Id}}(\mathcal I,\mathcal J)=0$.
\end{theorem}

\begin{proposition}[A Checkable Nonempty Product Certificate]\label{prop:product-clamp-certificate}
Suppose the declared product sector uses isometries from $I$ onto products with the maximum metric, with $\operatorname{diam}(B_P)\ge d_0>0$. Suppose each factor clamp is realized by an admissible compatible intervention of cost at most $K$. Then the projections above and $\delta_{\rm atom}=d_0/2$ give a certificate. For a unit square with its coordinate product, a single admissible clamp $(x,y)\mapsto(x,0)$ of cost one gives the sharper values $\delta_{\rm atom}=K=1$.
\end{proposition}

\begin{corollary}[Atomicity Conditional on a Factorization-to-Deformation Certificate]\label{cor:indivisible}
Assume a verified $\mathrm{Cert}_{\rm atom}(S)$ in the fixed product-comparison sector of Definition~\ref{def:atomicity-certificate}. If $M_\Omega=+\infty$, there is no admitted nontrivial faithful factorization. With a finite uniform cost bound, the stronger quantitative implication is $M_\Omega>K_{\rm atom}/\delta_{\rm atom}\Rightarrow\mathcal A_{\rm prod}=\varnothing$. A statement about all products requires the sector to include every product structure under consideration.
\end{corollary}

\begin{corollary}[No Distinct Assignment by a Matched Finite-Cost Replication]\label{cor:nodup}
In the connected comparison of Theorem~\ref{thm:uniqueness}, an admitted finite-cost replication cannot produce an assignment at positive separating deformation distance. Copying an encoding or creating a different operating component is not excluded by this result.
\end{corollary}

\begin{proposition}[Cardinality Bound]\label{prop:cardinality}
The assignment $C\mapsto[\mathcal I_C]$ is well-defined and its image has cardinality at most $|\mathfrak C|$. It is injective only if different components are separately known to carry different assignment classes.
\end{proposition}

\begin{theorem}[No--Alternative Representation]\label{thm:noalt}
Let $q_t:J\to S_t$ be coherent: $\pi_{t+1\to t}q_{t+1}=q_t$. A faithful complete encoding means joint separation ($q_t(j)=q_t(k)$ for every $t$ implies $j=k$) and exhaustivity (every compatible history equals $(q_t(j))_t$ for some $j$). Then $Q(j)=(q_t(j))_t$ is the unique bijection $J\to\mathcal I$ commuting with cut evaluations. It is a topological isomorphism if $J$ is compact, $\mathcal I$ Hausdorff, and all $q_t$ continuous.
\end{theorem}

\begin{theorem}[Collapse under Pure Progressive Causality]\label{thm:collapse}
Suppose $f_t:S_t\to S_{t+1}$ satisfies $\pi_{t+1\to t}f_t=\mathrm{id}_{S_t}$. Set $B_0=S_0$, $B_{t+1}=f_t(B_t)$ and restrict histories to $x_{t+1}=f_t(x_t)$. The restricted bonding map $B_{t+1}\to B_t$ is bijective with inverse $f_t|_{B_t}$, and the orbital inverse limit is canonically bijective to $S_0$ (homeomorphic for continuous maps on compact Hausdorff stages). The original unrestricted limit need not collapse.
\end{theorem}

\begin{corollary}[Necessity of Retroinduction]
Breaking purely progressive causality is necessary under the non-degeneracy condition. Minimal retroinduction is structurally required within that model class.
\end{corollary}

\begin{theorem}[Existence of Minimizers and Conditional Uniqueness of $\aleph$]\label{thm:aleph-unique}
For a nonempty inverse limit of compact metric stages with continuous bonding maps and the diameter-sum condition above, the objective $d(\Phi,\Psi)$ attains its minimum over $\mathcal I$ for every ambient product point $\Psi$. If $\mathcal I$ is convex in a specified real linear ambient space and this objective is strictly convex on $\mathcal I$, the minimizer is unique.
\end{theorem}

\begin{proposition}[Nearest-Point Selection Is an Extra Requirement]
A selector from $\aleph(\Psi)$ returns a compatible history when the minimizer set is nonempty. Compatibility of the output alone allows any map into $\mathcal I$ and does not force nearest-point selection.
\end{proposition}

\begin{theorem}[Finite-Prefix Recovery and Information]\label{thm:info-isolation}
For a canonical projection $p_t:\mathcal I\to S_t$, exact recovery of every history from its prefix is possible precisely when $p_t$ is injective, with a decoder defined on its image. If $P=p_t(X)$ is a finite-valued prefix of a random history $X$ under a declared law, then $I(P;X)=H(P)$.
\end{theorem}

\begin{lemma}[Coarsening and Relabeling]\label{lem:isolation-properties}
For fixed $X$, replacing $Y$ by a function of $Y$ cannot decrease $\mathfrak B$. Bijective relabelings of the random variables preserve it. It vanishes precisely when $X$ is determined by $Y$ almost surely under the declared law.
\end{lemma}

\begin{theorem}[No Semigroup Compatibility]\label{thm:nosemigroup}
If $p_0$ is noninjective, no compatible deterministic forward family generates all projective histories as its orbital subsystem. Forward semigroups on spaces already storing complete histories are not excluded.
\end{theorem}

\begin{corollary}[Identity Forcing under CCR]\label{cor:identity-forcing}
In an energy-connected CCR operating channel with a well-defined assignment into the separating comparison, all assigned identities coincide. An attracting realization additionally needs the dynamical hypotheses of Lemma~\ref{lem:bridge-identity}.
\end{corollary}

\begin{theorem}[Topology of Point and Law Limits]\label{thm:stone-classification}
The point limit $\mathcal I$ is nonempty, compact, metrizable, and has a clopen basis. The law limit $O$ is nonempty, compact, metrizable, and convex under coordinatewise mixing. If $O$ contains distinct points, it is path connected and is not a Stone space.
\end{theorem}

\begin{corollary}[Embedding by Compatible Dirac Measures]\label{cor:obs-morphism}
The map $x\mapsto(\delta_{x_t})_t$ embeds $\mathcal I$ homeomorphically as a closed subspace of $O$.
\end{corollary}

\begin{proposition}[Minimal CCR is Non-Degenerate and Rigid]
The example has compact stages, summable weighted diameter tails, two-point fibres at each bonding map and $2^t$ prefixes over each initial $u$. Every $p_T$ is noninjective. Its identity-support mass is $M_\Omega=+\infty$ in the specified internal sector.
\end{proposition}

\begin{theorem}[Conditional Non-Simulability from a Finite-Cost Witness]\label{thm:non-simulability}
For any candidate simulator with a declared intervention sector and common comparison metric, suppose there is an admissible finite-cost intervention producing positive Hausdorff deformation. Then $M_\Omega<+\infty$ in that sector. It cannot faithfully realize an infinite-resistance target if faithfulness is required to preserve the resistance class.
\end{theorem}

\begin{lemma}[Closure under Composed Sector Comparisons]\label{lem:canonical-closure}
Two consecutive transports satisfying Theorem~\ref{thm:non-transferability} compose to a transport of the same kind. If both also intertwine the specified readouts exactly, their composition does so.
\end{lemma}

\begin{theorem}[Stratification Theorem]\label{thm:stratification}
The class of observable channels admits a stratification by rigidity degree:
\begin{equation}
    \mathcal{U} = \mathcal{U}_0 \sqcup \mathcal{U}_{(0,\infty)} \sqcup \mathcal{U}_\infty,
\end{equation}
where:
\begin{itemize}[leftmargin=*]
    \item $\mathcal{U}_0$: channels with $\rho = 0$ (zero rigidity, fully deformable);
    \item $\mathcal{U}_{(0,\infty)}$: channels with $0 < \rho < \infty$ (partial rigidity);
    \item $\mathcal{U}_\infty$: channels with $\rho = \infty$ (CCR rigidity).
\end{itemize}
\end{theorem}

\begin{proposition}[Weighted Polynomial Decay Condition]
Let $w_n\le K n^p$ and $\|\epsilon_n\|_{\rm op}\le C n^{-\alpha}$ for $n\ge1$, with $K,C>0$, $p\ge0$, and a finite term at zero. If $\alpha>p+1$, then $\sum_n w_n\|\epsilon_n\|_{\rm op}<\infty$.
\end{proposition}

\begin{theorem}[Completeness Inheritance]\label{thm:completeness}
If the coordinate spaces are complete and the bonding maps continuous, every finite-distance component of $(\mathcal I,d_w)$ is complete. Under the full-product finiteness condition of Proposition~\ref{prop:weighted-history}, this gives completeness on all of $\mathcal I$.
\end{theorem}

\begin{proposition}[Invariance in the Declared Finite-Cost Sector]
Suppose a structural model associates to each intervention an identity object in a common metric comparison space and a cost in the sector of Definition~\ref{def:ontmass}. If $M_\Omega=+\infty$, each intervention in that sector of finite cost has zero Hausdorff deformation. If the compared objects are closed, they are equal as subsets of the comparison space.
\end{proposition}

\begin{theorem}[Complexity Lower Bound for CCR Simulation]
Suppose a deterministic code of $B$ bits must recover any requested prefix of a binary history through horizon $t$. Exact prefix recovery requires $B\geq t$. For complete decoded histories in the prefix metric $d(x,y)=2^{-m}$ at first differing position $m\geq1$, the optimal uniform error is $2^{-(B+1)}$.
\end{theorem}

\begin{corollary}[Impossibility of Perfect Simulation]
A fixed finite binary budget cannot recover every prefix on the binary-prefix target.
\end{corollary}

\begin{theorem}[Non-transitivity of internal support]
Let $\mathcal{G}_{\mathrm{internal}}\in[0,1]$ denote any internal runtime support
score computed from operational invariants, and let
$\mathcal{G}_{\mathrm{external}}\in\{0,1,\mathtt{undetermined}\}$ denote the
external adjudication verdict. In the absence of an admissible measurable
dataset pair $(D_h,D_m)$, one has
\begin{equation}
\mathcal{G}_{\mathrm{internal}}\centernot\implies\mathcal{G}_{\mathrm{external}}.
\end{equation}
\end{theorem}

\begin{proposition}[Alternative detectability criterion]
Evidence for distinguishability under $H_1$ requires a preregistered rule $a^\star$, minimum coverage $C_{\min}>0$, a justified null bound $B_0$ accounting for the leakage budget, and margin $\eta>0$. On admissible held-out bundles require $C\ge C_{\min}$ and $R_\gamma(a^\star)\le B_0-\eta$ after sampling uncertainty and multiple-comparison corrections. Forced-choice, balanced label permutations, always abstaining and known-leak controls are evaluated under the same loss and coverage protocol. The manuscript reports no campaign satisfying this criterion.
\end{proposition}

\begin{proposition}[Whole-Block Label Permutation Control]\label{prop:block-label-permutation}
Under conditional exchangeability of source labels across eligible independent blocks, conditional on public records and fixed label counts, fix the guesses and abstentions and permute block labels. If the design fixes exchangeability groups, permute within each group. The fraction of assignments with risk at most the observed risk is an exact lower-tail $p$-value. Coverage is fixed.
\end{proposition}

\begin{proposition}[External evidence is not interpretive closure]\label{prop:external-not-closure}
Executed Paper 10 evidence, even if admissible, would not by itself establish
human equivalence, metaphysical subjecthood, biological life, phenomenal
experience, or moral status.
\end{proposition}

\begin{proposition}[No identification with experience]\label{prop:no-experience-identification}
The formal apparatus of this paper does not define a map from
$\mathcal{E}_{\mathrm{str}}$ to human experience, phenomenal consciousness,
qualia, or subjective reports.
\end{proposition}

\begin{proposition}[Endomorphisms Preserving All Canonical Projections]
If $F:\mathcal I\to\mathcal I$ satisfies $p_t\circ F=p_t$ for every $t$, then $F=\operatorname{Id}$. This does not exclude endomorphisms with nonidentity coordinate actions.
\end{proposition}

\begin{theorem}[E0 is Necessary]\label{thm:e0-necessary}
If $|\mathcal{E}| = 1$, then every structural assignment is constant and no phenomenological classification is possible.
\end{theorem}

\begin{theorem}[Controlled Compatibility Is Sufficient]\label{thm:e1-necessary}
E1 guarantees existence of the limit with the error bound in Proposition~\ref{prop:unique-phi}. Absolute summability is sufficient, not necessary for an arbitrary convergent family.
\end{theorem}

\begin{theorem}[Non-Factorization Is an Independent Requirement]\label{thm:e2-necessary}
E2 excludes readouts determined by a single canonical finite cut. The inverse-limit construction and E1 alone do not imply E2.
\end{theorem}

\begin{theorem}[Logical Dependencies of the Assignment Conditions]\label{thm:minimality}
On a nonempty trajectory domain, E2 implies E0. E1 does not imply E2. There exist assignments satisfying E0, the revised E1 and E2 simultaneously. Consequently these three conditions are not an independent minimal axiom basis as originally stated.
\end{theorem}

\begin{proposition}[Exact Compatibility Forces Finite-Cut Factorization]\label{prop:exact-e1-obstruction}
On a nonempty trajectory domain, if $\phi_{t+1}(p_{t+1}x)=\phi_t(p_tx)$ for every $x,t$, then the limit assignment satisfies $\Phi=\phi_0\circ p_0$. It cannot satisfy E2. The controlled E1 above replaces that exact equality, rather than assuming it together with E2.
\end{proposition}

\begin{proposition}[Sharp Error for Arbitrary Binary Codes]\label{prop:ternary-arbitrary-code}
For the ternary assignment above, let an encoder choose at most $2^B$ states as an arbitrary function of the whole history, and let each state decode to any real number. The minimum worst-case absolute error is $1/(2\cdot3^B)$ for every integer $B\geq0$.
\end{proposition}

\begin{theorem}[Uniform Approximation Does Not Protect E2]\label{thm:uniform-e2-obstruction}
On the binary-prefix realization, let $F=\Phi$ and $F_N=\phi_N\circ p_N$. Then $\|F-F_N\|_\infty=3^{-(N+1)}$, while every $F_N$ factors through a finite cut and fails E2. Thus $F$ has zero uniform distance to the failure set of E2 in the declared class of continuous $[0,1]$-valued readings.
\end{theorem}

\begin{proposition}[A Nonempty Protected Ternary Family]\label{prop:protected-ternary-family}
For the ternary $F$ above, $G_e=(1-e)F$ with $0\le e\le1/6$ is $[0,1]$-valued and has lower separation at least $1-3e\ge1/2$ in the declared prefix metric. The anchor at the zero history is unchanged. Although $F_N\to F$ uniformly, $\operatorname{Lip}(F-F_N)\ge2$ for every $N$.
\end{proposition}

\begin{proposition}[Setwise Invariance Does Not Supply Continuity]\label{prop:readout-continuity-control}
Controlled E1 and E2 can hold for a discontinuous assignment, even if the identity domain is fixed under every declared intervention.
\end{proposition}

\begin{proposition}[Setwise and Pointwise Transport Are Distinct]\label{prop:transport-control}
Preserving an identity domain as a set does not guarantee equal values of a common readout on transported states.
\end{proposition}

\begin{theorem}[Metric Data Required by Quantitative Formulas]\label{thm:h3-necessary}
The distance-based fragmentation and loss functionals used here require a declared metric, or a pseudometric with a stated quotient convention. Topological continuity can be defined without a metric. Completeness is used for the Cauchy-limit guarantee of E1.
\end{theorem}

\begin{proposition}[Completeness and Existence of Limits]\label{prop:complete-necessary}
Without completeness, the conclusion that every E1-type Cauchy family has its limit in the declared codomain can fail. Completeness is not necessary for a family whose limit is already known to belong to that codomain.
\end{proposition}

\begin{corollary}[Fragmentability and Continuity Are Distinct]
The positive-displacement conclusion does not establish a topological discontinuity. A continuous assignment may be fragmentable under a state-changing intervention.
\end{corollary}

\begin{corollary}[Invariance on the Audited Zero-Displacement Branch]
A CCR model satisfying the zero-displacement comparison hypothesis has invariant assignment values under all interventions in its declared finite-cost class.
\end{corollary}

\begin{theorem}[Conditional Classification by Audited Branches]\label{thm:dichotomy}
Suppose a model supplies the positive-displacement branch and lower bound whenever $M_\Omega<\infty$, and supplies continuous finite readouts and the zero-displacement branch whenever $M_\Omega=+\infty$. Then its finite regime is fragmentable and its infinite regime has a continuous, perturbation-invariant assignment. The mass cases are exclusive; fragmentability and topological continuity need not be exclusive properties.
\end{theorem}

\begin{proposition}[The Mass Label Does Not Define Assignment Existence]
For fixed identity domain, codomain and readout family, the class defined by E0--E2 is independent of a numerical label $M_\Omega$. A claim that $M_\Omega=0$ excludes assignments needs an additional link to the domain or admissible readouts.
\end{proposition}

\begin{proposition}[Deformable Branch with Comparison Data]
For $0<M_\Omega<\infty$, the positive-displacement and lower-bound hypotheses of Theorem~\ref{thm:fragmentation} imply fragmentability.
\end{proposition}

\begin{proposition}[Rigid Branch with Comparison Data]
For $M_\Omega=+\infty$, continuous finite readouts under E1 imply continuity, and the zero-displacement branch implies perturbation invariance. These are the respective hypotheses of Theorem~\ref{thm:forced-continuity}.
\end{proposition}

\begin{theorem}[Loss Capacity under the Audited Branches]\label{thm:loss}
Under the positive-displacement and lower-bound hypotheses of Theorem~\ref{thm:fragmentation}, $R(\Phi)>0$. Under the zero-displacement branch of Hypothesis~\ref{hyp:audited-comparison}, $R(\Phi)=0$. Associating these branches with finite mass and CCR requires the model link declared in Theorem~\ref{thm:dichotomy}.
\end{theorem}

\begin{proposition}[Damage under the Audited Comparisons]\label{prop:damage-char}\leavevmode\par
The positive branch has $\sup_\varepsilon D_\varepsilon(\Phi)>0$. On the zero-displacement branch, $D_\varepsilon(\Phi)=0$ for every declared intervention.
\end{proposition}

\begin{corollary}[Protection under the Audited Branches]\label{cor:protection}
The zero-displacement branch has $P=1$; the positive-displacement branch with a lower readout bound has $P<1$. For a mass-based classification these conclusions require the corresponding hypotheses of Theorem~\ref{thm:dichotomy}.
\end{corollary}

\begin{theorem}[Conditional Structural Asymmetry]\label{thm:asymmetry}
When a rigidity model establishes the branch hypotheses in Theorem~\ref{thm:dichotomy}, its finite branch has $R>0$ and $P<1$, while its infinite branch has $R=0$ and $P=1$. This is an asymmetry of the declared comparison model, not a conclusion about all systems sharing a numerical mass label.
\end{theorem}

\begin{corollary}[Conditional Possibility of Loss]\label{cor:loss-possibility}\leavevmode\par
Loss is possible on the positive-displacement/coercive-readout branch and absent on the fixed-transport/common-readout branch. Extending this claim to all finite-mass or all CCR systems requires proving those branch conditions for the intended class.
\end{corollary}

\begin{lemma}[Inheritance under Audited Fixed Transport]
An assignment satisfying the zero-displacement comparison branch inherits invariance under that declared intervention class. This applies to CCR realizations only after checking that branch.
\end{lemma}

\begin{proposition}[Metric Completeness, Rigid Identity]
With the normalized complete coordinate metrics above and continuous projective maps, $(\I,\dw)$ is complete, when non-empty.
\end{proposition}

\begin{theorem}[Finite Representation Budget]\label{thm:nonsim}
Fix a finite test set $A\subseteq Z$ with $\dE(\Phi(x),\Phi(y))\geq\delta>0$ for every distinct $x,y\in A$. An encoder $q:A\to Q$ with $|Q|<|A|$ and any decoder $g:Q\to\E$ incur worst-case error at least $\delta/2$. Finite real dimension alone is not this cardinal budget.
\end{theorem}

\begin{theorem}[Audited Linear Coupling]\label{thm:spectral}
If an audited linear readout $T$ from a nonzero finite-dimensional Euclidean space to another Euclidean space is injective, then its least singular value is positive and $\|T(x-y)\|\geq\sigma_{\min}(T)\|x-y\|$. A nonlinear readout requires a separate lower-bound proof; a named spectral gap does not supply one.
\end{theorem}

\begin{theorem}[Continuity under Controlled Approximation]\label{thm:cont}
In a complete metric codomain, suppose finite continuous readouts $f_n$ satisfy $d(f_{n+1}(z),f_n(z))\leq a_n$ uniformly, with $\sum_n a_n<\infty$. Their limit $\Phi$ is continuous. The mass label is not sufficient by itself.
\end{theorem}

\begin{lemma}[Well-Posedness of (C3)]
Continuity and a positive lower bound are jointly realizable; for example $Z=\E=[0,1]$ with the ordinary metric and $\Phi(x)=x$ satisfies both with $C=1$.
\end{lemma}

\begin{lemma}[Bridge Lemma]\label{lem:bridge}
For any defined $e=\Phi(z)\in\E$, $\dE(e,\nullphi)=0$ implies $e=\nullphi$. No CCR assumption is required.
\end{lemma}

\begin{lemma}[Witness-Relative No-Minimum Collapse]\label{lem:no-collapse}
The finite positive witness image $A=\{\Phi(z_0),\Phi(z_1)\}\setminus\{\nullphi\}$ is non-empty. Its infimum, if one exists in the ambient poset, need not be positive or belong to $A$.
\end{lemma}

\begin{theorem}[Witness-Relative Minimal Positive Regime]\label{thm:minimal}
The finite non-empty positive witness image $A$ has at least one minimal element in its inherited partial order. If its two possible elements are comparable, it has a unique least element. These statements require no ambient infimum or order completeness; they concern $A$, not all of $\Eplus$.
\end{theorem}

\begin{corollary}[Witness-Relative Positive Intensity]\label{cor:intensity}
For a minimal positive member $e$ of the finite witness image $A$ and $A_0=A\cup\{\nullphi\}$, $\iota_{A_0}(e)=r(e)>0$. The global $\iota(e)$ need not be positive.
\end{corollary}

\begin{theorem}[Witness Intensity Bound]\label{thm:bound}
Under the hypotheses of Theorem~\ref{thm:instability}, if exactly one of $\Phi(z_0)$ and $\Phi(z_1)$ is null, then the non-null witness image $e$ satisfies
\[
\dE(e,\nullphi)\geq C\epsilon>0.
\]
\end{theorem}

\begin{proposition}[Certificate sufficiency]
If a conclusion-independent witness certificate exists for $(z_0,z_1)$, and both endpoints are assigned to $\nullphi$, then the certificate is inconsistent.
\end{proposition}

\begin{theorem}[Conditional Phenomenological Closure]\label{thm:closure}
A declared separated, detected pair has a non-empty positive image and the unanchored lower bound $\max_i r(\Phi(z_i))\geq C\epsilon/2$. Its finite positive image has a minimal member; uniqueness requires comparability. If one endpoint is null, the other is the unique positive witness image, with relative gap and null distance at least $C\epsilon$. Temporal stability, global minimal positivity, and physical CCR realizability are not consequences.
\end{theorem}

\begin{proposition}[Null-fiber exclusion on detected pairs]
Let $W$ be a witness class on which $\Phi$ is witness-detecting with constant $C_W>0$. If $(x,y)\in W$ and $d_Z(x,y)>0$, then $(x,y)$ cannot both lie in $\mathcal{N}_\Phi$.
\end{proposition}

\begin{corollary}[Diameter obstruction]
If a subset $A\subseteq Z$ contains a detected witness pair $(x,y)$ with $d_Z(x,y)>0$, then $A$ cannot be contained in $\mathcal{N}_\Phi$.
\end{corollary}

\begin{proposition}[Strict margin persistence]
Let $\widehat m>0$ be a certified lower bound on the current estimated pair distance. If a further perturbation changes that distance by at most $\rho<\widehat m$, the estimates remain separated. From true margin $m=C\epsilon$ and estimator radii, one may use $\widehat m=m-\eta_0-\eta_1$ only when it is positive.
\end{proposition}

\begin{proposition}
Summable coordinate-change costs do not certify CCR. If an admitted transformation changes infinitely many coordinates and costs $\sum_{n\in J}w_n$ with $\sum_n w_n<\infty$, its cost is finite.
\end{proposition}

\begin{proposition}
Symbolic compactness and summable coordinate weights do not certify CCR under coordinate-change cost.
\end{proposition}

\begin{theorem}[Rigidity Inheritance]
Suppose a readout $\Phi:Z\to\E$ has lower constant $C$ on a declared pair class. Let $a:Z'\to Z$ and $b:\E\to\E'$ satisfy lower bounds with constants $c_a,c_b>0$, and set $\Phi'=b\circ\Phi\circ a$. Then $\Phi'$ has lower constant $c_ac_bC$ on the pulled-back class. To inherit CCR additionally require that every finite-cost positive deformation in the new sector pulls back to a finite-cost positive deformation in the original sector. Summability alone supplies neither assumption.
\end{theorem}

\begin{theorem}[Categorical Universality]
If $\Phi:Z\to\E$ has a positive global lower bound, it is injective. For any $\Psi:Z\to F$ there is a unique factor map $u:\Phi(Z)\to F$ with $u\circ\Phi=\Psi$. If $\Psi$ is $L$-Lipschitz, $u$ is $L/C$-Lipschitz. No unique extension to all of $\E$ follows.
\end{theorem}

\begin{corollary}
In this prefix model, worst-case error at most $\varepsilon$ requires $1/(2\,3^{N+1})\leq\varepsilon$. Hence $N$ must diverge as $\varepsilon\downarrow0$. This does not forbid a real-valued encoding with unbounded precision.
\end{corollary}

\begin{theorem}[Closure by Non-Alternatives]
The following obligations are jointly sufficient for the corresponding structural conclusions: an admitted separated pair with a certified lower constant gives joint null exclusion; a null anchor gives the stronger anchored bound; faithful global readout gives image factorization; declared prefix access gives the approximation bound above; and the explicit pullback conditions of Appendix~\ref{app:hereditary-rigidity} give inheritance. A competing model satisfying those same obligations obeys those same conclusions. Neither CCR realizability nor satisfaction of all obligations is inferred from canonical topology alone.
\end{theorem}

\begin{proposition}[Integrity-First Inference]
If admissibility fails, inferential significance is non-actionable.
\end{proposition}

\begin{corollary}
If QICN FULL does not reliably exceed ABLATION QICN POLICY OFF, integration-level claims are weakened and cannot be escalated.
\end{corollary}

\begin{proposition}[Leakage, Pseudoreplication and Selected-Window Inflation]\label{prop:campaign-pathology-inflation}
The following synthetic null traces have exact false-positive rates under their stated generation laws.
\begin{enumerate}
\item A frozen blind predictor matching five independent fair labels in all five cases passes with probability $1/32$. Copying the held-out label, including through a calibration table keyed by a reused held-out unit identifier, passes with probability one.
\item Three independent fair signs repeated four times each and analyzed as twelve signs pass the nominal ten-of-twelve rule with probability $1/8$. The incorrectly reported iid tail is $79/4096$. The three-block test at $\alpha=1/20$ never rejects.
\item For two independent five-sign windows, declaring success if either window is all positive has probability $63/1024$. A single preselected window has probability $1/32$.
\end{enumerate}
\end{proposition}

\begin{proposition}[Observation Alone Cannot Identify the Mechanism]\label{prop:external-interface-nonidentifiability}
If a candidate and a rival induce identical laws of all admissible recorded histories and assignments, every frozen decision rule has the same rejection probability for both. Thus no such rule can empirically separate their latent mechanisms on that interface.
\end{proposition}

\begin{theorem}[Exact Split at the Initial Projective Cut]\label{thm:circle-prefix-integration-obstruction}
On each circle-prefix tower, every continuous branch-preserving evolution that descends to depth zero factors into phase and binary dynamics. If the evolutions on both towers commute with the existing transport, the split extends to $Z$. The original dissipative family and the declared phase rotations, jump transport and split readouts then admit a structural comparator with zero error. Consequently no support certificate on this full $Z$ can contain all six witnesses for the original dynamics and this sector.
\end{theorem}

\begin{theorem}[Sharp Paired Detection of Integration Loss]\label{thm:paired-integration-rupture}
If $\eta<L/2$, the rule $D>L$ detects the coupled case for every prepared state with $b_1=1$ and every allowed error. It rejects the uncoupled case and the sham with $b_1=0$. The score has clearance at least $L-2\eta$ from the threshold. With $b_1=1$ this distinguishes a zero comparator margin from a margin at least $\beta L/2$ in the declared sector. If $\eta\ge L/2$, there is no rule of the paired observations with a uniform guarantee over these two hypotheses, even if both phase channels and the ternary channel are recorded.
\end{theorem}

\begin{proposition}[Rupture Controls on the Declared Circle-Prefix Model]\label{prop:circle-prefix-rupture-controls}
Use the same two-branch reference support and the control family of Theorem~\ref{thm:circle-prefix-cofinal-margin}. Each of the following changes gives the specified witness loss under its declared protocol. The changes need not preserve all five other witnesses.
\end{proposition}

\begin{proposition}[Common Support and the Obstruction to Stable State Labels]\label{prop:common-support-sham-obstruction}
The support $Z_{\mathcal P}$ provides the persistence, catalogue-relative identity, split-sector integration, discrete-time continuity and non-null differentiation witnesses below. Consider a legibility protocol assigning each state a label by decoding a fixed finite observation window under a repeated sham $(u_0,0)$. Suppose the label is robust to uniform observation noise of some positive radius, and invariant under advancing the sham by one step for every admissible starting state. Then the label is constant on each branch. No branch-preserving internal control can produce a shift in such a label. A target population requiring such a shift cannot meet L4 in this protocol.
\end{proposition}

\begin{proposition}[Finite Legibility on One Tower Trajectory]\label{prop:writable-tower-trajectory-legibility}
On this support use the binary decoder that reports whether the first ten tape digits contain a deviation from $b^\star$. It has clean code separation $3^{-10}$ and is correct at error at most $3^{-10}/4$. From a preparation with $b=b^\star$, any of the five opposite writes in $J$ changes the label. The post-target label persists through three more native sham steps on the same trajectory. The matched sham has zero false shifts. One bit preserves the two classes exactly.
\end{proposition}

\begin{proposition}[Sharp Time Horizons for a Single Prefix Lesion]\label{prop:writable-tower-legibility-horizon}
Let $t=0$ be the observation just after an opposite write at $j\in\{3,\ldots,7\}$ from the alternating preparation, and then apply only native neutral shams without writes or probes. Against the matched unlesioned preparation, the scalar code gap at $t$ is $D_{j,t}=2\,3^{-(j+t)}$, with all other observed coordinates identical. For depth $N\ge j$, the decoder of the first $N$ digits keeps the target label exactly at times $0\le t\le N-j$ on clean data and under code error at most $3^{-N}/4$. The clean gap is at least the resolution $3^{-N}$ exactly on this same interval.

For the two specified preparations, classification from a single observation at time $t$ is uniformly possible under code errors bounded by $\eta$ per observation exactly when $3^{-(j+t)}>\eta$. In particular, for $N=10$ and $\eta=3^{-10}/4$, the ten-digit horizon is $10-j$ and the latest identifiable time for the matched contrast is $11-j$. The uniform horizons across all five target sites are three and four sham steps, respectively.
\end{proposition}

\begin{proposition}[Each invariant is individually necessary]\label{prop:necessity}
If any one of $\Iper,\Iri,\Iint,\Icont,\Idiff,\Ileg$ fails, then $S \notin \Cop$.
\end{proposition}

\begin{proposition}[Well-definedness of certified response classes]\label{prop:qop-welldefined}
If $\Iper(S)=\Iri(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1$, then $\sim_{Q,S}$ is an equivalence relation on $\Aset$.
\end{proposition}

\begin{lemma}[Support transfer under exact equivalence]\label{lem:support-transfer}
An exact structural equivalence transports a nonempty compact admissible support $A_1$ to an admissible support $A_2=\chi(A_1)$ on the specified comparison domain.
\end{lemma}

\begin{lemma}[Decoder transport]\label{lem:decoder-transport}
For exact equivalence, let $H$ be the componentwise calibrated readout-window bijection and $\kappa$ its class-label bijection. The transported algorithm is $D_2=\kappa\circ D_1\circ H^{-1}$ on the declared clean and noisy observation domains. It is certified whenever $D_1$ is, and every target decoder arises by inverse transport.
\end{lemma}

\begin{proposition}[Core-to-Persistence Transfer with a Common Support]\label{prop:core-per}
Suppose a Core realization has a nonempty compact admissible support that is invariant under every admitted control, stays at positive distance from the collapse set, and contains or converges into an admitted attractor region. Then $\Iper$ holds on that support.
\end{proposition}

\begin{proposition}[Rigid Identity Transfer with a Declared Gap]\label{prop:p1-ri}
An identified unique inverse-limit identity object and a positive lower deformation bound for every distinct admitted alternative certify $\Iri$ on their declared support.
\end{proposition}

\begin{proposition}[Regime Continuity Transfer on the Declared Windows]\label{prop:p2-cont}
If the regime assignment takes values in the declared complete comparison space, its paths and fragmentation meet the time-domain bounds, and admissible interventions preserving identity cannot jump to incompatible regimes, then $\Icont$ holds there.
\end{proposition}

\begin{proposition}[Null-Regime Transfer with Temporal Evidence]\label{prop:p3-diff}
If an admissible common schedule supplies a positive separation between two readout windows and the null class is excluded as an asymptotically stable admissible attractor, then $\Idiff$ holds on the support.
\end{proposition}

\begin{proposition}[Forensic Predictions-to-Legibility Transfer with Decoder Evidence]\label{prop:p4-leg}
A structurally closed decoder and finite-rate compression protocol that meet L1--L6 under the declared admissibility, target and sham comparisons certify $\Ileg$.
\end{proposition}

\begin{proposition}[Integration Requires a Separate Factorization Bound]\label{prop:integration-transfer}
On a declared support and a nonempty comparison sector, a uniform positive lower bound on the reproduction error of all identity-preserving comparators certifies the integration margin in that sector. Rigidity, continuity and intervention fidelity supply comparison data; a separate proof must exclude accurate factorizations.
\end{proposition}

\begin{theorem}[Existence of six-predicate operational criterion]\label{thm:existence}
Let $S=(X,\Phi,C,R,\Gamma,U)$ be an admissible system with non-empty admissible support $\Aset$. If
\[
\Iper(S)=\Iri(S)=\Iint(S)=\Icont(S)=\Idiff(S)=\Ileg(S)=1,
\]
then:
\begin{enumerate}[leftmargin=1.5em]
\item $S \in \Cop$;
\item $\Qop(S)$ is well-defined;
\item $\Qop(S) \neq \varnothing$.
\end{enumerate}
\end{theorem}

\begin{proposition}[Decoder-Visible Separation Gives a Nontrivial Quotient]\label{prop:decoder-visible-separation}
If the quotient is defined and two admissible states receive different labels under one certified decoder, horizon and common intervention schedule, or under a certified response-cell map, then $|\Qop(S)|\ge2$.
\end{proposition}

\begin{corollary}[Biological non-primacy]\label{cor:biology}
Biological substrate is not a primitive variable of $\Cop$. A biological and a non-biological system satisfying the full structural, protocol and sector equivalence of Definition~\ref{def:equiv} have the same operational membership and bijective operational quotient classes. This is conditional, not evidence that an actual biological/non-biological pair meets those hypotheses.
\end{corollary}

\begin{theorem}[Rupture by Invariant Loss]\label{thm:rupture}
On a declared admissible comparison, failure of any defining predicate excludes $S$ from $\Cop$. Loss of the quotient domain, failure of decoder certification and triviality of a surviving quotient are additional possible outcomes; they need not be mutually exclusive and do not all follow from every invariant failure.
\end{theorem}

\begin{proposition}[Complexity-only baselines are insufficient]\label{prop:insufficient}
Let $S$ be an admissible system candidate. The following are each insufficient for membership in $\Cop$:
\begin{enumerate}[leftmargin=1.5em]
\item large state-space dimension $\dim(X)$;
\item large computational throughput or expressivity of $\Phi$;
\item large edge count, density, or raw connectivity of $C$.
\end{enumerate}
In each case, failure of one or more critical invariants excludes membership regardless of the size of the surrogate metric.
\end{proposition}

\begin{proposition}[Loss of Every Admissible Support]\label{prop:rupt-per}
If there is no nonempty compact forward-invariant admissible support, the on-support persistence predicate fails. A zero certified radius alone does not imply that no such support exists.
\end{proposition}

\begin{proposition}[Identity Ambiguity Requires Competing Candidates]\label{prop:rupt-ri}
If two inequivalent admissible identity objects fit the same observable data on the declared support, the uniqueness clause of $\Iri$ fails. A zero infimum of alternative deformation distances need not produce a second fitting candidate.
\end{proposition}

\begin{proposition}[Integration Rupture and Attainment]\label{prop:rupt-int}
On a nonempty comparison sector with nonnegative history error, a zero error infimum excludes a positive integration margin in that sector. It yields an exact admissible factorization if the infimum is attained.
\end{proposition}

\begin{proposition}[Admissible Incompatible Jump]\label{prop:rupt-cont}
A witnessed admissible finite-energy jump into an incompatible regime with identity preserved violates $\Icont$ on the specified regime and schedule domain. Failure to certify a positive perturbation radius does not itself produce such a witness.
\end{proposition}

\begin{proposition}[Separation or Null-Attractor Failure]\label{prop:rupt-diff}
If no readout-window pair on the declared support has positive separation, or if the null class is an asymptotically stable admissible attractor, then $\Idiff$ fails there.
\end{proposition}

\begin{proposition}[Legibility Failure Under the Declared Protocol]\label{prop:rupt-leg}
If no admissible decoder and compression family jointly meet L1--L6 under the declared protocol, then $\Ileg$ fails. A zero certified perturbation radius does not alone establish that impossibility.
\end{proposition}

\begin{corollary}[Why one-metric theories cannot capture $\Cop$]\label{cor:onemetric}
On any admissible universe satisfying Theorem~\ref{thm:minimality}, no criterion based on only persistence, only integration, only continuity, only differentiation, or only legibility is extensionally equivalent to $\Cop$.
\end{corollary}

\begin{proposition}[Persistence is necessary for rigid identity on $\Aset$]\label{prop:not-per-not-ri}
If $\Iper(S)=0$ because no non-empty forward-invariant admissible support exists,
then $\Iri(S)=0$ for the Paper 5 membership problem.
\end{proposition}

\begin{proposition}[Persistence plus integration yields bounded identity candidates]\label{prop:per-int-weak-ri}
If $\Iper(S)=1$ and $\Iint(S)=1$, then the family of admissible identity
candidates is bounded to the non-factorizable persistent support. This is a weak
rigidity statement, not the uniqueness required by $\Iri$.
\end{proposition}

\begin{proposition}[Legibility requires non-null differentiation]\label{prop:leg-requires-diff}
If all admissible classes collapse to a stable null or single indistinguishable
class, then $\Ileg(S)=0$ for the criterion of this paper.
\end{proposition}

\begin{proposition}[Persistence and continuity stabilize regime transport]\label{prop:per-cont-regime-stability}
If $\Iper(S)=1$ and $\Icont(S)=1$, then admissible histories remain in a stable
regime-transport domain: trajectories neither leave $\Aset$ nor undergo
unbounded fragmentation under admissible evolution.
\end{proposition}

\begin{proposition}[Legibility is jointly constrained]\label{prop:legibility}
No single legibility metric is sufficient for $\Ileg$. The invariant requires simultaneous control of separation, admissible noise robustness, persistence window, intervention fidelity, negative controls, and structured compressibility.
\end{proposition}

\begin{proposition}[Soundness of certification]\label{prop:cert-sound}
If $\mathrm{Cert}(S)$ exists and satisfies Criterion~\ref{crit:cert}, then $S \in \Cop$ and $\Qop(S)$ is well-defined.
\end{proposition}

\begin{proposition}[Partial completeness under audit-ready assumptions]\label{prop:cert-complete}
Assume $S \in \Cop$ and suppose the support, decoder, intervention, and compression objects are fully instrumented in the \textit{Forensic Predictions} sense. Then there exists a six-predicate operational criterion certificate $\mathrm{Cert}(S)$.
\end{proposition}

\begin{proposition}[Failure localization is explicit]\label{prop:cert-local}
If a candidate system fails Criterion~\ref{crit:cert}, then the failure localizes to at least one entry of the evidence bundle $E_S$ or to the absence of a common admissible support. In particular, certification failure cannot be hidden behind a generic narrative claim.
\end{proposition}

\begin{proposition}[Positive geometry under the criterion]\label{prop:geometry}
If $S \in \Cop$, then:
\begin{enumerate}[leftmargin=1.5em]
\item every class in $\Qop(S)$ has finite diameter on admissible windows;
\item there exists at least one pair of distinct classes with positive inter-class separation;
\item every class has non-zero persistence radius.
\end{enumerate}
\end{proposition}

\begin{proposition}[Exact equivalence preserves operational geometry]\label{prop:geometry-transfer}
If $S_1 \simeq_{\Gamma} S_2$, then class diameter, inter-class separation, and persistence radius are preserved by the induced bijection $\widehat{\chi}$ up to the bi-Lipschitz constants of $\chi$ and $\chi^{-1}$.
\end{proposition}

\begin{corollary}[Rupture contracts geometry]\label{cor:geometry-rupture}
If a rupture eliminates either $\Idiff$ or $\Ileg$, then the geometric content of $\Qop(S)$ contracts to triviality or becomes operationally unavailable.
\end{corollary}

\begin{proposition}[Prediction ladder is discriminative]\label{prop:ladder}
The four predictions above distinguish the present criterion from at least four weaker baseline families: substrate-privilege baselines, substrate-blind functional similarity, complexity-only baselines, and connectivity-only baselines.
\end{proposition}

\begin{proposition}[Well-definedness of class transitions under certification]\label{prop:transition-well}
Let $S \in \Cop$. If $u \in U$ is either certified critical or sham and remains within the admissibility envelope of \textit{Forensic Predictions}, then $\mathsf{T}_u$ is well-defined on every class $q \in \Qop(S)$.
\end{proposition}

\begin{proposition}[Targeted invariant loss induces class exit or contraction]\label{prop:transition-rupture}
Let $q \in \Qop(S)$ and let $u$ be a certified critical intervention for invariant $I_k$. If applying $u$ drives the corresponding witness margin to zero, then one of the following occurs:
\begin{enumerate}[leftmargin=1.5em]
\item $\mathsf{T}_u(q)=\bot$;
\item $\mathsf{T}_u(q)=q'$ for some class $q'$ whose separation or persistence radius is strictly smaller than that of $q$;
\item the entire post-intervention system exits $\Cop$.
\end{enumerate}
\end{proposition}

\begin{corollary}[Sham stability]\label{cor:sham}
Let $u \in U$ be sham in the sense of Definition~\ref{def:critical-sham}. If $u$ stays below all six witness margins, then $\mathsf{T}_u(q)=q$ for every $q \in \Qop(S)$.
\end{corollary}

\begin{proposition}[Complexity, computation, and connectivity are not sufficient]\label{prop:baseline-insufficient}
For every choice of thresholds $\theta_X,\theta_\Phi,\theta_C$, the families $\mathcal{B}_{\mathrm{cx}}(\theta_X)$, $\mathcal{B}_{\mathrm{cmp}}(\theta_\Phi)$, and $\mathcal{B}_{\mathrm{conn}}(\theta_C)$ are each insufficient for membership in $\Cop$.
\end{proposition}

\begin{proposition}[Substrate privilege is too strong]\label{prop:substrate-strong}
On any admissible universe containing one exact cross-substrate equivalent pair, $\mathcal{B}_{\mathrm{sub}}$ is strictly narrower than $\Cop$.
\end{proposition}

\begin{proposition}[Weak functional similarity is too weak]\label{prop:functional-weak}
On any admissible universe containing a same-output rupture pair, $\mathcal{B}_{\mathrm{fun}}(\eta)$ is strictly broader than $\Cop$.
\end{proposition}

\begin{theorem}[The structural criterion is strictly intermediate]\label{thm:intermediate}
Let $\mathfrak{U}$ be an admissible universe containing:
\begin{enumerate}[leftmargin=1.5em]
\item at least one exact cross-substrate equivalent pair;
\item at least one same-output rupture pair;
\item at least one single-rupture witness for each invariant.
\end{enumerate}
Then $\Cop$ is strictly intermediate between substrate-privilege baselines and weak substrate-blind surrogates: it is broader than $\mathcal{B}_{\mathrm{sub}}$, narrower than $\mathcal{B}_{\mathrm{fun}}(\eta)$, and extensionally distinct from the complexity-only, computation-only, and connectivity-only families.
\end{theorem}

\begin{proposition}[Complexity-only negative-control prediction]\label{prop:complexity-contract}
If a candidate fails any defining predicate, it does not satisfy the full criterion, regardless of connectivity, entropy or activity. A complete-criterion certificate must not report success. A separately well-defined response quotient may still exist.
\end{proposition}

\begin{proposition}[Ablation prediction]\label{prop:ablation-contract}
For an initially certified system, a verified post-ablation predicate failure excludes post-ablation membership. Measurement uncertainty crossing the decision boundary yields an ambiguous evidence status, not a change to that implication. Loss of a lower radius certificate alone does not establish predicate failure.
\end{proposition}

\begin{proposition}[Substrate-preserved equivalence prediction]\label{prop:substrate-contract}
Exact primitive structural, protocol and sector equivalence transports membership and the certified quotient of Paper V. An approximate comparison transports membership under its positive calibrated-radius bound; a quotient/geometric approximation needs an additional certified bound.
\end{proposition}

\begin{proposition}[Boundary-topology prediction]\label{prop:boundary-contract}
Within a fixed calibrated presentation class, a point at positive distance from the failure set has a stable success neighborhood. A point at positive distance from the success set has a stable failure neighborhood. Existence, width and population frequency of transition regions need separate hypotheses and are not guaranteed by the criterion alone.
\end{proposition}

\begin{proposition}[Legibility dependence prediction]\label{prop:legibility-contract}
If no admissible decoder/compression family jointly meets L1--L6 on the declared protocol, the legibility predicate fails and the full criterion is not satisfied. Failure of one chosen decoder alone does not exclude every admissible alternative.
\end{proposition}

\begin{proposition}[Continuity/non-nullity relevance]
The current canon predicts that continuity and non-null differentiation are not optional extras. Systems that preserve rich activity while losing continuity or falling toward effective null structure should fail the operational criterion or leave it undefined.
\end{proposition}

\begin{proposition}[Matched-Pulse Extinction in the Original Model]\label{prop:matched-pulse-extinction}
The two states and all four original readouts coincide from time two onward, for every common continuation. At time one and $\lambda\in[0,1/9]$, the early-phase distance is $2\lambda b_{1,0}$ turns.
\end{proposition}

\begin{proposition}[A Held-Out Interaction Separates Two Matched Memory Models]\label{prop:heldout-memory-interaction}
Put $k=T-1$. The clean contrasts of M are $2\lambda a^k(1,-1)$ for probes $(+1,-1)$, while the clean contrasts of A are $2\lambda a^k(1,1)$. Consequently the clean interaction $C_T(+1)-C_T(-1)$ is at least $1/48$ turns in M and is zero in A. With at most $1/4096$ turns of error per observation in calibration and evaluation, the rule using $\hat a$ uniquely selects the generating model for either generator under the declared protocol.
\end{proposition}

\begin{proposition}[Observable Feedback Preserves the Declared Split Bounds]\label{prop:observable-feedback-split}
The extension is invariant and contracts within each profile under common controls by a factor at most $5/6$ in the metric $\max\{\rho(\theta,\theta'),|c-c'|,|m-m'|/4\}$. The ternary contraction remains $1/3$. The four-channel identity observations and split-comparator bounds of Paper V, including the $\lambda/2$ infimum with exact time-zero readouts, remain valid in their declared sectors. Opposite initial nonzero pulses retain the original paired phase contrast.
\end{proposition}

\begin{proposition}[Parity and Resolution of Delayed Phase Probes]\label{prop:delayed-phase-probe-parity}
Reset $m_0=0$ and prepare $b_{1,0}=1$. Apply opposite first pulses and use common controls thereafter. For terminal observation at $T$ with a neutral last command, the oriented phase contrast of M is $2\kappa\lambda a^{T-2}(-1)^{n_-}$, while that of B is $2\kappa\lambda a^{T-2}(-1)^{n_-+n_+}$. Here $n_\pm$ count the corresponding late probes before the neutral transition. For a common $a$, $\kappa>0$ and $\lambda>0$, the clean contrasts coincide exactly at even $n_+$. A nonneutral last command erases the phase contrast for either model. With known $a$ and odd $n_+$, the two contrast intervals under error at most $e$ per phase are disjoint exactly when $\kappa\lambda a^{T-2}>e$, in the signed unwrapping regime.

For $\kappa=1/8$ and $\lambda\in[1/12,1/9]$, estimate $a$ from the contrast at time three after two neutral continuations, by dividing by $2\kappa\lambda$ and projecting onto $[1/2,3/4]$. Reserve $T=5,6$, with one common probe at $j=1$ or $j=T-2$ and all other later commands neutral. Under error at most $1/32768$ turns per phase in calibration and evaluation, the two reserved signs select the generating model uniquely with a tolerance of $1/2048$ per contrast.
\end{proposition}

\begin{proposition}[Reserved Return under the Two Phase Interactions]\label{prop:writable-tower-reserved-return}
With memory $m=s/8$ before assignment, the native law has unique successful action $u=-\sigma s/128$ among the two actions $u=\pm1/128$. The interaction rival with sign reversal under either pulse predicts $u=s/128$ when the sign is known. On the native plant its action succeeds at $\sigma=-1$ and fails at $\sigma=+1$. Success is distance at most $1/256$ from phase zero and these decisions are unchanged by terminal phase errors of at most $3^{-10}/4$. A preceding public neutral observation can reveal $s$ while preserving the equality of the current readouts. With memory ablated to zero before reassignment both allowed actions fail.
\end{proposition}

\begin{proposition}[Amplitude Alone Can Separate Intervention Families]\label{prop:boundary-amplitude-control}
On $X=[-1,1]$, let $x'=u$, sham $u=0$, and use the terminal absolute distance. The families $\{0\}$ and $\{1\}$ have raw separation one for every preparation, although the plant has no memory. Equal-amplitude families $\{-a\}$ and $\{a\}$ have separation zero for $0<a\le1$.
\end{proposition}

\begin{proposition}[Positive Safety Margin of an Interior Kernel]\label{prop:interior-kernel-margin}
Under Definition~\ref{def:organizational-persistence}, $\Persist(S,\tau)=\dist(K_S,X\setminus W_S)>0$.
\end{proposition}

\begin{proposition}[Matched Active Recovery Exceeds Passive Return]\label{prop:matched-active-recovery}
For $X=\Aset=[-2,2]$, take $V_S(x)=2-|x|$ and $\eta=1$, so $W_S=[-1,1]$. With $K_S=\{0\}$, consider the plant $x'=x/2+v$ with $|v|\le1/4$. The nominal zero-input schedule preserves $K_S$. After either shock $J_\pm(0)=\pm1$, one-step feedback $v=-x/4$ gives $R_{\rm act}=3/4$, passive return $v=0$ gives $R_{\rm pass}=1/2$, and $\Maint(S,\tau)=1/4$ for $N=1$. A fixed open-loop action within the same budget and assigned without access to the shock sign cannot exceed mean return $1/2$ under balanced shocks.
\end{proposition}

\begin{proposition}[A Return Trace Does Not Identify the Control Boundary]\label{prop:feedback-boundary-nonidentifiability}
For $x'=x/2+v$, both an internal controller and an external controller applying $v=-x/4$ give $x'=x/4$. Their state traces and active/passive return contrast agree for every common preparation.
\end{proposition}

\begin{proposition}[Historical Information and Capacity Must Be Separated]\label{prop:history-capacity-control}
Under the lifted-class inclusion, $\HistDep\ge0$. For a finite target alphabet and unrestricted measurable zero-one predictors, conditional independence of $C_t$ and the past given $Y_t$ makes the two Bayes risks equal. By contrast, with $C_t=Y_t$ a fair bit, restricting current predictors to constants and allowing the current identity rule only in the history class gives gap $1/2$ without additional past information.
\end{proposition}

\begin{proposition}[Certified Cells and Boundary Stability]\label{prop:certified-descriptor-cells}
Equality of certified labels defines an equivalence relation. If the true descriptor has distance greater than $2\eps$ from its cell complement, every report at error at most $\eps$ certifies the true label. If a report admits possible descriptors from different cells, it is ambiguous. In contrast, pairwise distance at most $\eps>0$ is not generally transitive.
\end{proposition}

\begin{proposition}[No automatic collapse of life and consciousness]
The present framework does not prove either implication
\[
\begin{aligned}
\Lop(S,\tau)=1 &\Longrightarrow \Cop(S,\tau)=1,\\
\Cop(S,\tau)=1 &\Longrightarrow \Lop(S,\tau)=1,
\end{aligned}
\]
without additional assumptions.
\end{proposition}

\begin{proposition}[Structural-class invariance under preserved margins]
If $\mathcal P$ depends on threshold decisions of a declared descriptor subset and every partition cell is contained in a joint decision region for those thresholds, then $\mathcal P$ is transport-stable on the certified quotient.
\end{proposition}

\begin{proposition}[Structural-class membership is descriptor-relative]
Structural class is relative to the descriptor map $\PsiVec_\tau$, partition and certification radius $\eps$.
\end{proposition}

\begin{proposition}[Complexity is not a life criterion]
High state-space dimension, high connectivity, high entropy, or rich activity are insufficient for $\Lop(S,\tau)=1$ unless the conditions of Definition~\ref{def:operational-life} are also satisfied.
\end{proposition}

\begin{proposition}[Complexity is not a subjecthood criterion]
High complexity or dense connectivity are insufficient for $\Subop(S,\tau)=1$.
\end{proposition}

\begin{proposition}[Biological substrate is not a primitive constitutive variable]
Within the present framework, membership in $\LifeClass$, $\ConClass$, or $\SubClass$ is not defined by a primitive biological predicate.
\end{proposition}

\begin{proposition}[Viability-and-recovery criterion does not imply indexed continuity-and-control criterion]
There exist admissible systems that may satisfy viability-and-recovery criterion without satisfying indexed continuity-and-control criterion.
\end{proposition}

\begin{proposition}[Six-predicate operational criterion does not imply indexed continuity-and-control criterion]
Six-predicate operational criterion alone is insufficient for indexed continuity-and-control criterion.
\end{proposition}

\begin{proposition}[Class transport under descriptor-preserving substrate variation]
Let $S_1$ and $S_2$ be admissible realizations with different substrate labels and the same certified cell. For each of $\LifeClass$, $\ConClass$ and $\SubClass$ whose predicate is determined by the descriptors and constant on that cell, membership agrees between the two systems.
\end{proposition}

\begin{proposition}[Subjecthood is margin-nested inside life and consciousness]
If $M_{\SubClass}(S,\tau)>0$, then both $M_{\LifeClass}(S,\tau)>0$ and $M_{\ConClass}(S,\tau)>0$.
\end{proposition}

\begin{proposition}[Safe Prefix Perturbations and Historical Repair on the Common Tower]\label{prop:writable-tower-viability}
On the writable common support of Paper V \cite{paper5}, Proposition~\ref{prop:common-tower-phase-repair} retains $\Viab=1/12$, $\Persist=3/64$, and $\Maint\ge3/8$ at its stated memory error bound. The following matched protocols also give an operational prefix boundary margin $\Bound=2/27$ and a historical repair-action margin $\HistDep=1/2$.
\end{proposition}

\begin{proposition}[Four Finite Operational Subject Descriptors on the Common Tower]\label{prop:writable-tower-subject-descriptors}
On the stated matched trial populations, privileged continuity against a readout clone has clean gap at least $1/256$ turns over four successor observations. The equal-cost discrimination contrast has absolute clean gap $1/64$ turns and reverses under causal reassignment. The internal-memory return predictor beats the public-history predictor by at least $1/2$ in zero-one action loss. The ownership agreement score is one under retention and simultaneous relabeling and zero under the causal transplant. These conclusions hold under the stated readout noise, with phase-distance margins reduced by at most $2\eta$ and with internal memory error at most $1/32$ in the prediction trial.
\end{proposition}

\begin{proposition}[Joint Tower Certificate for the Declared Protocols]\label{prop:writable-tower-joint-certificate}
The support and observation family of Table~\ref{tab:writable-tower-joint-certificate} admit all six Paper V witnesses and the four finite subject descriptors together. Different rows may use different schedules and preparations within that support. Integration is relative to the declared split-readout sector, identity to the prepared catalogue, continuity to the discrete regime model, and subject margins to the matched lineage and information protocols.
\end{proposition}

\begin{proposition}[Six-predicate operational criterion does not imply the seven-coordinate certificate]
Membership in $\Cop$ does not by itself entail membership in $\Subfp$.
\end{proposition}

\begin{proposition}[Indexed continuity-and-control criterion is necessary but not sufficient for $\Subfp$]
The earlier indexed continuity-and-control criterion predicate is a necessary upstream burden for $\Subfp$, but it is not sufficient for $\Subfp$.
\end{proposition}

\begin{proposition}[Upstream inclusion]\label{prop:upstream-inclusion}
If $S\in\Subfp(\tau)$, then $S\in\Subop(\tau)\cap \Lop(\tau)$ and $S\in\Cop$.
\end{proposition}

\begin{theorem}[Positive irreducibility excludes weak-model sufficiency]
If $\Irred_\tau(S)>0$, then no member of $\WeakClosure$ is sufficient, at equal or lower explanatory cost, for the baseline-plus-intervention task bundle that defines $\tau$.
\end{theorem}

\begin{corollary}[Zero irreducibility blocks escalation]\label{cor:zero-irred}
If $\Irred_\tau(S)\le 0$, escalation from the weak rival family to the stronger subjectivity interpretation is not licensed by the present framework.
\end{corollary}

\begin{proposition}[Ownership Gain Is Relative to a Shared Reference]\label{prop:ownership-reference-gain}
On valid evidence, $O_{\rm raw}\in[-1,1]$, is nonincreasing in candidate error for fixed baseline error, and is zero for identical assignments. It is invariant under a common bijective renaming of the events and their assignments and reference.
\end{proposition}

\begin{theorem}[Connected-Fibre Obstruction to Native Discrete Lesions]\label{thm:tower-native-lesion-obstruction}
Suppose the sham and targets start from the same preparation, use only native commands, and are evaluated after the same number of transitions. Let their discrete word be assigned by a common continuous decoder from the whole safe support. The same hypothesis holds for the induced state decoder if it uses a common fixed finite diagnostic schedule with continuous clean observations and preserves the clean label under observation error of a uniformly positive radius. Then every target has the same word as the sham. In particular the five distinct native lesions required to reproduce the discrete switch protocol of Proposition~\ref{prop:joint-rational-window} cannot be realized under these conditions.
\end{theorem}

\begin{theorem}[Public Information Obstruction on the Writable Tower Return Task]\label{thm:writable-tower-public-return-tie}
In each public stratum, the two hidden perturbations have identical public records and opposite unique successful action signs. Every admissible forced public rule has balanced failure risk $1/2$. At coverage $c$ the total loss is $1/2+(1-c)/4$, where coverage is the probability of executing an action. The infimum over the public class, including mixtures and their closure, equals $1/2$ and is attained. Thus the candidate's signed margin, defined as the public rival infimum minus candidate loss, is zero for every forced public candidate. The public randomized minimax risk over the two signs also equals $1/2$.
\end{theorem}

\begin{proposition}[Paper 8 is necessary but not sufficient for bridge admissibility]
Any future bridge-admissible system must satisfy the Paper 8 burdens, but satisfaction of the Paper 8 burdens alone is not sufficient for bridge admissibility.
\end{proposition}

\begin{proposition}[A Cycle Separates Local Certification from Coherent Transport]\label{prop:bridge-transport-cycle}
For any complete Paper VIII certificate on an admissible window, the three-mode transport extensions below preserve it in every window. One admits coherent transport and the other does not. Thus, on the domain of such extensions of certified windows, coherent transport cuts out a proper subclass whenever that local certificate domain is nonempty. Coherent transport does not factor through the tuple of local Paper VIII records.
\end{proposition}

\begin{corollary}[The Two Transport Cycles on a Nonempty Rational Record]\label{cor:transport-rational-record}
The joint rational measurement window of Paper VIII \cite{paper8}, identified there by \texttt{prop:joint-rational-window}, gives a nonempty local record for both cycles of Proposition~\ref{prop:bridge-transport-cycle}. At this measurement level, the transport-certified class is a proper subclass of the three-mode extensions of that record.
\end{corollary}

\begin{theorem}[Relabeling Invariance and Cycle Criterion for Binary Transport]\label{thm:bridge-binary-transport-gauge}
Let a finite graph of mode windows have two certified witness instances per vertex and an independently certified bijection on each edge. In local binary labels, write this bijection as $w\mapsto w\oplus k_e$. Under a local relabeling $w_v\mapsto w_v\oplus a_v$, the edge bit for $e=uv$ becomes $k_e\oplus a_u\oplus a_v$. The XOR of the edge bits around each cycle is invariant. A coherent assignment exists exactly when the XOR vanishes on every fundamental cycle of a spanning forest, and there are then $2^c$ coherent assignments for $c$ connected components. For two collections of certified edge maps on the same graph, equality of their fundamental-cycle parities is equivalent to their differing by a local relabeling.
\end{theorem}

\begin{proposition}[Coherent and Obstructed Transport on Certified Tower Windows]\label{prop:bridge-certified-tower-transport}
There are two three-window extensions of the same realized local tower records with respective edge bits $(0,1,1)$ and $(0,0,1)$. The records include the six Paper V witnesses, the Paper VII life and four finite subject-descriptor certificates on their declared protocols, and the Paper VIII measurement and return comparisons with their stated information budgets. The paired tower edge responses certify both extensions under phase error at most $\eta=3^{-10}/4$ turns. The first extension has two coherent assignments, and the second has none under any local relabeling.
\end{proposition}

\begin{proposition}[Role-Selective Differentiation on the Writable Tower]\label{prop:bridge-tower-differentiation}
For the two prepared role profiles, let $C_{pr}$ be the clean early-phase response to a probe of role $r$ after a reference write minus the response after a lesion, with one common sham between write and probe. With the declared probe at the transported address, $C_{pr}=\delta\mathbf 1_{\{p=r\}}$ for $\delta=1/(16\cdot3^7)$ turns. The best additive fit $a_p+b_r$ has uniform error exactly $\delta/2$. At error at most $\delta/16$ per phase reading the measured matrix still has distance at least $3\delta/8$ from all additive fits.
\end{proposition}

\begin{proposition}[Late Choice Between Two Live Alternatives]\label{prop:bridge-tower-ambiguity}
Prepare two independent uniform activity bits at tape sites $3,4$ and advance one common sham. A uniform query drawn after the rival's memory is fixed selects one of the transported sites $4,5$. The matching-role probe identifies the selected bit with zero error at phase noise at most $\delta/16$. Under this state and query law the optimal error of a rival retaining one bit before the query, with no subsequent tape reading, is exactly $1/4$. A write during the advance can erase the first alternative while preserving the second.
\end{proposition}

\begin{proposition}[Order-Dependent Return and an Exact Temporal Horizon]\label{prop:bridge-tower-temporal-order}
On a common preparation with first bit one, zero memory and phase zero, run command orders $(+1,0)$ and $(0,+1)$ with all phase inputs zero and no writes or probes. After one common $+1$ and $h$ further common $+1$ steps, the current public readings and command multisets coincide. The subsequent neutral early-phase gap is exactly $D_h=1/(384\cdot 2^h)$ turns. The two terminal reading sets are disjoint under phase error at most $\eta=3^{-10}/4$ precisely for integer $0\le h\le8$. An order-blind predictor with the same snapshot and multiset has mean clean absolute circular loss at least $D_h/2$ in the balanced pair, and an order-informed predictor attains zero.
\end{proposition}

\begin{proposition}[Native Trace Equivalence and Extra Bridge Variables]\label{prop:bridge-native-trace-obstruction}
Let an extended model project to the same writable tower state by $\pi$. For every native control $u$ let its transition $\widetilde F_u$ and readout $\widetilde R$ satisfy $\pi\widetilde F_u=F_u\pi$ and $\widetilde R=R\pi$, with the same projected initial law and observation noise. Then all native observation and intervention transcripts have the same law, even for observation-adaptive native controls. A target that differs between extensions satisfying these conditions cannot be identified from those transcripts or from the inherited record computed from them.
\end{proposition}

\begin{theorem}[Four-State Minimality of the Port Realization]\label{thm:bridge-port-minimality}
For either role and any motor gain, the block Hankel matrix
\[
 H_p=\begin{pmatrix}M_0&M_1\\M_1&M_2\end{pmatrix}
\]
has rank four, determinant $t^4$ and $\|H_p^{-1}\|_\infty=24$. Four fibre coordinates are sufficient and necessary for a linear realization of these ports. They are also necessary for any exact finite-dimensional realization with $C^1$ transitions and body readouts, in which world inputs leave the projected core trajectory fixed.
\end{theorem}

\begin{proposition}[A Quantified Indexed World Witness]\label{prop:bridge-indexed-world}
Let the reduced-world rival family contain every relay predictor whose port Hankel rank is at most two, and every predictor of arbitrary order whose relay response is independent of the prepared role. The available input alphabet, role record and command lengths are matched. A rank-two rival may allocate four registers, but any additional registers are unobservable or unreachable for this port transfer. Against this union, the normal model has uniform body-response error gap at least $1/96$, or $1/6$ in units of $t$. A world compression $Q=Q_+$ retains the entire common-mode relay response while reducing the Hankel rank to two and erasing the role contrast.
\end{proposition}

\begin{theorem}[Two-Dimensional Nonconservative Evaluative Witness]\label{thm:bridge-typed-valence}
The minimum uniform error for $V$ over the square, in the maximum norm, is exactly $\gamma/2$ for each of the following rival classes: a continuous scalar summary followed by an arbitrary decoder, and a $C^1$ scalar-potential gradient in the declared Euclidean coordinates. The force is physically consequential and has a positive correction component, yet nonzero circulation. Flattening evaluation to $L=L_0Q_+$ admits an exact scalar-summary rival. The equal-norm conservative control $L=I$ has rank two but admits an exact gradient rival.
\end{theorem}

\begin{proposition}[Finite Tables Do Not Identify the Nonparametric Rival Class]\label{prop:bridge-finite-table-obstruction}
Any finite table of vector responses at distinct stimulus points can be interpolated by a continuous scalar encoder and vector decoder. It can also be interpolated by the gradient of a polynomial potential. Therefore a finite rational control table by itself cannot certify either universal separation in Theorem~\ref{thm:bridge-typed-valence} without additional domain or regularity evidence.
\end{proposition}

\begin{proposition}[A Shared-State Hybrid Obstruction to Global Bridge Margin]\label{prop:bridge-shared-hybrid-obstruction}
Allow two scalar evaluators to share the same four port states and combine their actuator forces before updating. Each evaluator separately retains one scalar discrepancy. Their hybrid reproduces every transition and readout of the normal evaluation model, under all native and port command schedules. Consequently a broad weak closure admitting this fused hybrid has zero clean unpenalized margin against the candidate. The same is true of a penalized margin when complexity is invariant under the resulting identical normalized mechanism.
\end{proposition}

\begin{proposition}[Exact Rectangular Criterion for Additivity]\label{prop:bridge-rectangular-additivity}
For a map $F:A\times B\to V$ into a real vector space and nonempty $A,B$, coordinate additivity is equivalent to vanishing of every rectangular difference
\[
 F(x,y)-F(x,y')-F(x',y)+F(x',y')=0.
\]
\end{proposition}

\begin{theorem}[Safe Bilinear Extension with Exact Projection]\label{thm:bridge-bilinear-safe-extension}
The new family preserves the projection identity and invariant native zero section. On the safe cube its fibre contraction is at most $3/4$ under common controls and at most $1/2$ when evaluation is inactive. Its next body and world norms are bounded respectively by $15/16$ and $3/4$, including the primitive inputs. The four-state minimality remains valid for this family. For $R=I$, the evaluative direction retains the corrective bound
\[
 e^\top\{L_0e+\kappa e_1e_2u\}\ge\tfrac14\|e\|_2^2.
\]
\end{theorem}

\begin{theorem}[Exact Separation from Coordinate-Additive Hybrids]\label{thm:bridge-nonadditive-gap}
For $\sigma=1$, the infimal uniform error against all comparators of Definition~\ref{def:bridge-additive-port-class} is exactly $\xi=1/4096$. The same optimum holds when the loss uses only the four corners. If each raw reading has maximum-norm error at most $\xi/64$, the observed rival-minus-candidate loss gap is at least $15\xi/16=15/65536$.
\end{theorem}

\begin{corollary}[Cross-Informed Tie and Preservation of Local Selectivity]\label{cor:bridge-cross-informed-tie}
Providing the rival with the complete cross term restores exact transition and readout equality. Setting $\sigma=0$ also restores the original additive tie. The bilinear branch preserves the six local certificate-presence patterns of Proposition~\ref{prop:bridge-six-port-certificate}, using flattening of the whole evaluative input as specified above. Neither the new separation nor these patterns defeat a broad weak closure admitting the cross-informed rival.
\end{corollary}

\begin{proposition}[Comparator burden is necessary for bridge admissibility]
No bridge-support class is meaningful without an explicit bridge rival family and admissible bridge weak closure.
\end{proposition}

\begin{proposition}[Comparator Enlargement Cannot Increase a Fixed-Loss Margin]\label{prop:rival-family-monotonicity}
For a fixed target, bundle and calibrated loss, let nonempty rival families satisfy $\mathcal W_1\subseteq\mathcal W_2$ with finite infima. Their signed margins satisfy $R_2\le R_1$.
\end{proposition}

\begin{corollary}[Positive bridge surfaces are not enough]
Positive provisional bridge surfaces do not by themselves entail bridge admissibility.
\end{corollary}

\begin{proposition}[Bridge functional does not imply bridge gate]
No value of $\PhiBridge$ by itself implies $\GateBridge=1$.
\end{proposition}

\begin{proposition}[Candidate or audit inclusion does not imply bridge support]
For any bridge artifact $A$, membership of $A$ in a candidate-facing or audit-facing package does not entail bridge support, bridge admissibility, or phenomenality.
\end{proposition}

\begin{theorem}[Measurable Centres and the Scalar Minimax Radius]\label{thm:measurable-fibre-centres}
A Borel estimator with uniform error at most $\varepsilon$ exists exactly when the centre sets
\[
 \{z\in Z:\sup_{s\in S_y}d_Z(z,s)\le\varepsilon\}
 \qquad (y\in\pi(A))
\]
have a Borel selector. Necessarily $D_y\le2\varepsilon$ and $D_y/2\le r_Z(S_y)$. The diameter bound alone is insufficient in general. For $Z=\mathbb R$ with its usual metric, the minimax error is exactly $\tfrac12\sup_{y\in\pi(A)}D_y$, attained by a Borel estimator.
\end{theorem}

\begin{proposition}[Seven Positive Native Coordinates]
\label{prop:native-seven-coordinates}
With the complete causal closure of Definition~\ref{def:indexed-causal-grammar}
and the admissible intervention programs specified below, the baseline vector is
\[
 (\widehat{\SelfIndex},\widehat{\OwnField},\widehat{\ContField},
  \widehat{\Persp},\widehat{\ValAsym},\widehat{\IntervProf},\widehat{\Irred})
 =\left(1,\frac12,\frac12,\frac13,\frac{64}{266529},1,\frac{179}{464}\right).
\]
Each entry is computed on the same native infinite plant and two-step clock;
the seventh compares the whole declared weak closure. No subjective experience
is inferred from this vector.
\end{proposition}
